CREATE OR REPLACE FUNCTION public.company_ensure_schema(p_company text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $functionx$
DECLARE command text;
BEGIN
 IF p_company !~ '^c_[a-f0-9]{16}$' THEN RAISE EXCEPTION 'Company unavailable' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('company-schema:'||p_company,0));
 IF to_regclass('public.'||p_company||'_employees') IS NOT NULL THEN RETURN; END IF;
 PERFORM set_config('check_function_bodies','off',true);
 FOR command IN SELECT value FROM jsonb_array_elements_text($template_json$["CREATE SCHEMA demo_hub_auth;","REVOKE ALL ON SCHEMA demo_hub_auth FROM PUBLIC,anon,authenticated;","GRANT USAGE ON SCHEMA demo_hub_auth TO service_role;","CREATE TABLE public.demo_hub_feature_flags (LIKE public.hub_feature_flags INCLUDING ALL);","ALTER TABLE public.demo_hub_feature_flags ENABLE ROW LEVEL SECURITY;","REVOKE ALL ON public.demo_hub_feature_flags FROM PUBLIC,anon,authenticated;","GRANT SELECT,INSERT,UPDATE,DELETE ON public.demo_hub_feature_flags TO service_role;","CREATE TABLE public.demo_hub_manager_stepup_attestations (LIKE public.hub_manager_stepup_attestations INCLUDING ALL);","ALTER TABLE public.demo_hub_manager_stepup_attestations ENABLE ROW LEVEL SECURITY;","REVOKE ALL ON public.demo_hub_manager_stepup_attestations FROM PUBLIC,anon,authenticated;","GRANT SELECT,INSERT,UPDATE,DELETE ON public.demo_hub_manager_stepup_attestations TO service_role;","CREATE TABLE public.demo_hub_manager_identities (LIKE public.hub_manager_identities INCLUDING ALL);","ALTER TABLE public.demo_hub_manager_identities ENABLE ROW LEVEL SECURITY;","REVOKE ALL ON public.demo_hub_manager_identities FROM PUBLIC,anon,authenticated;","GRANT SELECT,INSERT,UPDATE,DELETE ON public.demo_hub_manager_identities TO service_role;","CREATE TABLE public.demo_work_order_inspection_signatures (LIKE public.work_order_inspection_signatures INCLUDING ALL);","ALTER TABLE public.demo_work_order_inspection_signatures ENABLE ROW LEVEL SECURITY;","REVOKE ALL ON public.demo_work_order_inspection_signatures FROM PUBLIC,anon,authenticated;","GRANT SELECT,INSERT,UPDATE,DELETE ON public.demo_work_order_inspection_signatures TO service_role;","CREATE TABLE public.demo_ops_ride_manuals (LIKE public.ops_ride_manuals INCLUDING ALL);","ALTER TABLE public.demo_ops_ride_manuals ENABLE ROW LEVEL SECURITY;","REVOKE ALL ON public.demo_ops_ride_manuals FROM PUBLIC,anon,authenticated;","GRANT SELECT,INSERT,UPDATE,DELETE ON public.demo_ops_