e_inspection_submissions_operator_id_fkey FOREIGN KEY (operator_id) REFERENCES public.demo_employees(id) ON DELETE SET NULL;","ALTER TABLE public.demo_ride_inspection_submissions ADD CONSTRAINT demo_ride_inspection_submissions_supervisor_id_fkey FOREIGN KEY (supervisor_id) REFERENCES public.demo_employees(id) ON DELETE SET NULL;","ALTER TABLE public.demo_ride_inspection_submissions ADD CONSTRAINT demo_ride_inspection_submissions_transcriber_id_fkey FOREIGN KEY (transcriber_id) REFERENCES public.demo_employees(id) ON DELETE SET NULL;","ALTER TABLE public.demo_ride_inspection_answers ADD CONSTRAINT demo_ride_inspection_answers_submission_id_fkey FOREIGN KEY (submission_id) REFERENCES public.demo_ride_inspection_submissions(id) ON DELETE CASCADE;","ALTER TABLE public.demo_ride_defects ADD CONSTRAINT demo_ride_defects_answer_id_fkey FOREIGN KEY (answer_id) REFERENCES public.demo_ride_inspection_answers(id) ON DELETE CASCADE;","ALTER TABLE public.demo_ride_defects ADD CONSTRAINT demo_ride_defects_asset_id_fkey FOREIGN KEY (asset_id) REFERENCES public.demo_assets(id) ON DELETE SET NULL;","ALTER TABLE public.demo_ride_defects ADD CONSTRAINT demo_ride_defects_bridged_work_order_id_fkey FOREIGN KEY (bridged_work_order_id) REFERENCES public.demo_work_requests(id) ON DELETE SET NULL;","ALTER TABLE public.demo_ride_defects ADD CONSTRAINT demo_ride_defects_resolved_by_fkey FOREIGN KEY (resolved_by) REFERENCES public.demo_employees(id) ON DELETE SET NULL;","ALTER TABLE public.demo_ride_defects ADD CONSTRAINT demo_ride_defects_submission_id_fkey FOREIGN KEY (submission_id) REFERENCES public.demo_ride_inspection_submissions(id) ON DELETE CASCADE;","INSERT INTO demo_hub_auth.settings(id,require_manager_verification) VALUES(true,false);","INSERT INTO public.demo_hub_feature_flags SELECT * FROM public.hub_feature_flags;","CREATE OR REPLACE FUNCTION public.demo_ops_manual_folder_sources(p_source text)\n RETURNS text[]\n LANGUAGE sql\n IMMUTABLE STRICT\n SET search_path TO ''\nAS $function$\n  SELECT CASE\n    WHEN p_source IN ('mgr.xls','MGR 2.xls') THEN ARRAY['mgr.xls','MGR 2.xls']::text[]\n    WHEN p_source IN ('zipper.xls','zipper 2.xls') THEN ARRAY['zipper.xls','zipper 2.xls']::text[]\n    ELSE ARRAY[p_source]::text[]\n  END;\n$function$;","CREATE OR REPLACE FUNCTION public.demo_hub_photo_replace(p_token uuid, p_action text, p_original_id uuid, p_photo_id uuid DEFAULT NULL::uuid, p_sha256 text DEFAULT NULL::text, p_bytes integer DEFAULT NULL::integer, p_reason text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nDECLARE actor public.demo_employees%ROWTYPE; original public.demo_work_order_photos%ROWTYPE; photo public.demo_work_order_photos%ROWTYPE; request public.demo_work_requests%ROWTYPE;\nBEGIN\n SELECT * INTO actor FROM public.demo_hub_actor(p_token);\n IF NOT FOUND THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='28000'; END IF;\n IF actor.role<>'manager' THEN RAISE EXCEPTION 'Manager required' USING ERRCODE='42501'; END IF;\n IF p_action IS NULL OR p_action NOT IN ('permission','reserve','commit') THEN RAISE EXCEPTION 'Invalid action' USING ERRCODE='22023'; END IF;\n SELECT * INTO original FROM public.demo_work_order_photos WHERE id=p_original_id AND upload_state='ready' AND storage_path IS NOT NULL;\n IF NOT FOUND THEN RAISE EXCEPTION 'Photo not found' USING ERRCODE='P0002'; END IF;\n SELECT * INTO request FROM public.demo_work_requests WHERE id=original.work_request_id AND NOT hub_draft FOR UPDATE;\n IF NOT FOUND THEN RAISE EXCEPTION 'Order not found' USING ERRCODE='P0002'; END IF;\n SELECT * INTO original FROM public.demo_work_order_photos WHERE id=p_original_id FOR UPDATE;\n SELECT * INTO photo FROM public.demo_work_order_photos WHERE id=p_photo_id;\n IF original.superseded_at IS NOT NULL AND NOT COALESCE((photo.replacement_for=original.id AND photo.upload_state='ready'),false) THEN RAISE EXCEPTION 'Photo already replaced' USING ERRCODE='23505'; END IF;\n IF p_action='permission' THEN RETURN jsonb_build_object('can_replace',true,'request_id',request.id); END IF;\n IF p_reason IS NULL OR length(btrim(p_reason))<3 OR length(p_reason)>2000 THEN RAISE EXCEPTION 'Correction reason required' USING ERRCODE='22023'; END IF;\n IF photo.id IS NOT NULL AND (photo.replacement_for IS DISTINCT FROM original.id OR photo.uploaded_by IS DISTINCT FROM actor.id OR photo.replacement_reason IS DISTINCT FROM btrim(p_reason)) THEN RAISE EXCEPTION 'Replacement conflict' USING ERRCODE='23505'; END IF;\n IF p_action='reserve' THEN\n  IF p_photo_id IS NULL OR p_sha256 IS NULL OR p_sha256 !~ '^[0-9a-f]{64}$' OR p_bytes IS NULL OR p_bytes NOT BETWEEN 1 AND 5242880 THEN RAISE EXCEPTION 'Invalid photo' USING ERRCODE='22023'; END IF;\n  IF photo.id IS NOT NULL THEN\n   IF photo.sha256 IS DISTINCT FROM p_sha256 OR photo.byte_size IS DISTINCT FROM p_bytes THEN RAISE EXCEPTION 'Replacement changed' USING ERRCODE='23505'; END IF;\n  ELSE\n   INSERT INTO public.demo_work_order_photos(id,work_request_id,completion_id,photo_type,file_name,storage_path,uploaded_by,byte_size,sha256,upload_state,replacement_for,replacement_reason)\n   VALUES(p_photo_id,request.id,original.completion_id,original.photo_type,p_photo_id::text||'.jpg','work-orders/'||request.id||'/corrections/'||p_photo_id||'.jpg',actor.id,p_bytes,p_sha256,'pending',original.id,btrim(p_reason)) RETURNING * INTO photo;\n  END IF;\n  RETURN jsonb_build_object('id',photo.id,'path',photo.storage_path,'state',photo.upload_state);\n END IF;\n IF photo.id IS NULL THEN RAISE EXCEPTION 'Replacement not found' USING ERRCODE='P0002'; END IF;\n IF NOT EXISTS(SELECT FROM storage.objects WHERE bucket_id='hub-work-order-photos' AND name='demo/'||photo.storage_path AND (metadata->>'size')::bigint=photo.byte_size AND metadata->>'mimetype'='image/jpeg') THEN RAISE EXCEPTION 'Upload incomplete' USING ERRCODE='22023'; END IF;\n IF photo.upload_state<>'ready' THEN\n  UPDATE public.demo_work_order_photos SET superseded_at=now() WHERE id=original.id;\n  UPDATE public.demo_work_order_photos SET upload_state='ready' WHERE id=photo.id;\n  UPDATE public.demo_work_requests SET status=CASE WHEN verified_at IS NOT NULL THEN 'awaiting_verification' ELSE status END,verified_by=NULL,verified_at=NULL,verification_notes=NULL,version=version+1 WHERE id=request.id;\n  INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details) VALUES(request.id,actor.id,'photo_replaced',jsonb_build_object('reason',btrim(p_reason),'original_photo_id',original.id,'replacement_photo_id',photo.id));\n END IF;\n RETURN jsonb_build_object('id',photo.id,'state','ready');\nEND $function$;","CREATE OR REPLACE FUNCTION public.demo_hub_backup_photo_permission(p_secret text, p_photo_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare photo public.demo_work_order_photos%rowtype;\nbegin\n if p_secret is null or not exists(select 1 from vault.decrypted_secrets where name='demo_pms_hub_backup_export_secret' and decrypted_secret=p_secret)then raise exception 'Access denied' using errcode='28000';end if;\n select * into photo from public.demo_work_order_photos where id=p_photo_id and storage_path is not null and upload_state='ready';\n if not found then raise exception 'Photo unavailable' using errcode='P0002';end if;\n return jsonb_build_object('id',photo.id,'path',photo.storage_path,'sha256',photo.sha256,'bytes',photo.byte_size);\nend $function$;","CREATE OR REPLACE FUNCTION public.demo_hub_auth_delivery(p_id uuid, p_state text, p_receipt text DEFAULT NULL::text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$begin\n if p_state not in('sent','failed','uncertain')then raise exception 'Invalid state';end if;\n update demo_hub_auth.challenges set delivery_state=p_state,receipt=left(p_receipt,100)where id=p_id and delivery_state='sending';\nend $function$;","CREATE OR REPLACE FUNCTION public.demo_hub_completion(p_token uuid, p_action text, p_request_id uuid, p_photo_id uuid DEFAULT NULL::uuid, p_sha256 text DEFAULT NULL::text, p_bytes integer DEFAULT NULL::integer, p_notes text DEFAULT NULL::text, p_signature text DEFAULT NULL::text, p_signer_name text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nDECLARE\n  actor public.demo_employees%ROWTYPE;\n  request public.demo_work_requests%ROWTYPE;\n  photo public.demo_work_order_photos%ROWTYPE;\n  completion public.demo_work_completions%ROWTYPE;\n  v_self_assign_enabled boolean;\n  target_status text;\n  event_name text;\n  v_sig text;\nBEGIN\n  SELECT * INTO actor FROM public.demo_hub_actor(p_token);\n  IF NOT FOUND OR actor.id IS NULL THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='28000'; END IF;\n  IF p_action IS NULL OR p_action NOT IN ('permission','reserve','finish') THEN\n    RAISE EXCEPTION 'Invalid action' USING ERRCODE='22023'; END IF;\n\n  SELECT * INTO request FROM public.demo_work_requests WHERE id=p_request_id FOR UPDATE;\n  IF NOT FOUND OR (actor.role='manager' OR request.assigned_to=actor.id) IS NOT TRUE THEN\n    RAISE EXCEPTION 'Not found' USING ERRCODE='P0002'; END IF;\n  IF request.hub_draft AND (request.requester_id<>actor.id OR request.work_kind<>'completed_without_request') THEN RAISE EXCEPTION 'Not found' USING ERRCODE='P0002'; END IF;\n\n  v_self_assign_enabled := COALESCE(\n    (SELECT CASE WHEN COALESCE(request.is_test, false) THEN (enabled OR test_enabled) ELSE enabled END \n     FROM public.demo_hub_feature_flags WHERE feature = 'shop_self_assignment'), \n    false\n  );\n\n  -- Self-assignment must never give an unassigned manager completion authority.\n  -- Existing noncritical legacy orders retain their old rule while the flag is off.\n  IF (v_self_assign_enabled OR request.is_safety_critical OR request.safety_hold) AND\n     (request.assigned_to IS DISTINCT FROM actor.id OR actor.role NOT IN ('employee','shop','manager')) THEN\n    RAISE EXCEPTION 'Claim or receive the lead assignment before completing this job' USING ERRCODE='42501';\n  END IF;\n\n  IF p_action='permission' THEN\n    IF v_self_assign_enabled THEN\n      RETURN jsonb_build_object('revision',request.completion_revision,'can_complete',(request.status IN ('assigned','accepted','in_progress')));\n    ELSE\n      -- Live production behavior preserved\n      RETURN jsonb_build_object('revision',request.completion_revision,'can_complete',(request.status IN ('accepted','in_progress') AND (request.work_kind='completed_without_request' OR request.acknowledged_at IS NOT NULL)));\n    END IF;\n  END IF;\n\n  SELECT * INTO photo FROM public.demo_work_order_photos WHERE id=p_photo_id;\n  IF FOUND AND (photo.work_request_id<>request.id OR photo.uploaded_by IS DISTINCT FROM actor.id\n    OR photo.photo_type<>'completion' OR photo.assignment_revision<>request.completion_revision) THEN\n    RAISE EXCEPTION 'Photo conflict' USING ERRCODE='23505'; END IF;\n\n  -- A lost response can be retried without a second completion or event.\n  IF photo.completion_id IS NOT NULL AND photo.upload_state='ready' THEN\n    SELECT * INTO completion FROM public.demo_work_completions WHERE id=photo.completion_id;\n    IF completion.revision<>request.completion_revision THEN RAISE EXCEPTION 'Assignment changed; refresh' USING ERRCODE='23505'; END IF;\n    IF p_action='finish' AND completion.completion_notes IS NOT DISTINCT FROM btrim(p_notes)\n       AND completion.signature IS NOT DISTINCT FROM NULLIF(btrim(p_signature),'')\n       AND (completion.signature IS NULL OR public.demo_hub_signature_name_matches(p_signer_name,completion.signer_name)) THEN\n      RETURN jsonb_build_object('id',completion.id,'state',request.status);\n    END IF;\n    RAISE EXCEPTION 'Already completed' USING ERRCODE='23505';\n  END IF;\n\n  -- Check status eligibility\n  IF v_self_assign_enabled THEN\n    IF request.status NOT IN ('assigned','accepted','in_progress') THEN\n      RAISE EXCEPTION 'Order is not in an active work status' USING ERRCODE='42501';\n    END IF;\n  ELSE\n    -- Live production requirement preserved\n    IF NOT (request.status IN ('accepted','in_progress') AND (request.work_kind='completed_without_request' OR request.acknowledged_at IS NOT NULL)) THEN\n      RAISE EXCEPTION 'Accept the assignment before completing this order' USING ERRCODE='42501';\n    END IF;\n  END IF;\n\n  IF p_action='reserve' THEN\n    IF p_photo_id IS NULL OR p_sha256 IS NULL OR p_sha256 !~ '^[0-9a-f]{64}$'\n      OR p_bytes IS NULL OR p_bytes<1 OR p_bytes>5242880 THEN\n      RAISE EXCEPTION 'Invalid photo' USING ERRCODE='22023'; END IF;\n    IF photo.id IS NOT NULL THEN\n      IF photo.sha256 IS DISTINCT FROM p_sha256 OR photo.byte_size IS DISTINCT FROM p_bytes THEN\n        RAISE EXCEPTION 'Photo conflict' USING ERRCODE='23505'; END IF;\n    ELSE\n      IF (SELECT count(*) FROM public.demo_work_order_photos WHERE work_request_id=request.id AND photo_type='completion' AND assignment_revision=request.completion_revision AND superseded_at IS NULL)>=5 THEN\n        RAISE EXCEPTION 'Completion photo limit' USING ERRCODE='54000'; END IF;\n      INSERT INTO public.demo_work_order_photos(id,work_request_id,photo_type,file_name,storage_path,uploaded_by,byte_size,sha256,upload_state,assignment_revision)\n      VALUES(p_photo_id,request.id,'completion',p_photo_id::text||'.jpg',\n        'work-orders/'||request.id::text||'/completion/'||p_photo_id::text||'.jpg',actor.id,p_bytes,p_sha256,'pending',request.completion_revision)\n      RETURNING * INTO photo;\n    END IF;\n    RETURN jsonb_build_object('id',photo.id,'path',photo.storage_path,'state',photo.upload_state);\n  END IF;\n\n  IF p_notes IS NULL OR length(btrim(p_notes))<1 OR length(p_notes)>4000 OR photo.id IS NULL THEN\n    RAISE EXCEPTION 'Notes and photo required' USING ERRCODE='22023'; END IF;\n  IF NOT EXISTS(SELECT FROM storage.objects WHERE bucket_id='hub-work-order-photos'\n    AND name='demo/'||photo.storage_path AND (metadata->>'size')::bigint=photo.byte_size AND metadata->>'mimetype'='image/jpeg') AND NOT EXISTS(SELECT FROM public.hub_r2_receipts WHERE object_key=photo.storage_path AND byte_size=photo.byte_size AND sha256=photo.sha256) THEN\n    RAISE EXCEPTION 'Upload incomplete' USING ERRCODE='22023'; END IF;\n\n  -- Validate active electronic signature\n  -- NEVER manufacture a signature when input is blank!\n  v_sig := NULLIF(btrim(p_signature), '');\n  IF v_sig IS NOT NULL AND NOT public.demo_hub_valid_png_signature(v_sig) THEN\n    RAISE EXCEPTION 'Drawn PNG signature required' USING ERRCODE='22023';\n  END IF;\n  -- Requirement 1: Require explicit repair signature for safety-critical or safety-held work regardless of feature flag.\n  -- For routine noncritical work, require signature when self-assignment is enabled, and preserve legacy behavior when disabled.\n  IF (request.is_safety_critical OR request.safety_hold) OR v_self_assign_enabled THEN\n    IF v_sig IS NULL THEN\n      RAISE EXCEPTION 'Active electronic signature required' USING ERRCODE='22023';\n    END IF;\n    IF NOT public.demo_hub_signature_name_matches(p_signer_name,actor.full_name) THEN\n      RAISE EXCEPTION 'Typed signer name must match your employee record' USING ERRCODE='22023';\n    END IF;\n  END IF;\n\n  IF v_self_assign_enabled AND EXISTS (\n    SELECT 1 FROM public.demo_work_order_assignments a\n    WHERE a.work_request_id=request.id AND a.status='active'\n      AND a.employee_id<>actor.id AND a.assignment_role<>'lead'\n      AND NOT EXISTS (SELECT 1 FROM public.demo_work_order_contribution_signatures cs\n        WHERE cs.assignment_id=a.id AND cs.completion_revision=request.completion_revision)\n  ) THEN\n    RAISE EXCEPTION 'Every active crew member must sign their contribution or leave as no-work before lead completion' USING ERRCODE='22023';\n  END IF;\n\n  INSERT INTO public.demo_work_completions(\n    work_request_id,completed_by,completion_notes,completion_date,revision,\n    signature,signer_name,signed_at\n  )\n  VALUES(\n    request.id,actor.id,btrim(p_notes),\n    CASE WHEN request.work_kind='completed_without_request' THEN request.work_date::timestamp AT TIME ZONE 'UTC' ELSE now() END,\n    request.completion_revision,\n    v_sig,\n    CASE WHEN v_sig IS NOT NULL THEN actor.full_name ELSE NULL END,\n    CASE WHEN v_sig IS NOT NULL THEN now() ELSE NULL END\n  )\n  RETURNING * INTO completion;\n    \n  UPDATE public.demo_work_order_photos SET completion_id=completion.id,upload_state='ready' WHERE id=photo.id;\n\n  -- Transition order:\n  -- When self-assignment enabled:\n  --   Routine orders (is_safety_critical=false AND safety_hold=false) self-close to 'completed'.\n  --   Safety-critical orders (is_safety_critical=true OR safety_hold=true) move to 'awaiting_verification'; hold remains ACTIVE.\n  -- When self-assignment disabled:\n  --   Production behavior preserved (requires_verification determines 'awaiting_verification').\n  IF v_self_assign_enabled THEN\n    IF request.is_safety_critical OR request.safety_hold THEN\n      target_status := 'awaiting_verification';\n      event_name := 'work_submitted';\n    ELSE\n      target_status := 'completed';\n      event_name := 'work_completed';\n    END IF;\n  ELSE\n    IF request.is_safety_critical OR request.safety_hold OR request.requires_verification THEN\n      target_status := 'awaiting_verification';\n      event_name := 'work_submitted';\n    ELSE\n      target_status := 'completed';\n      event_name := 'work_completed';\n    END IF;\n  END IF;\n\n  UPDATE public.demo_work_requests \n  SET status = target_status,\n      hub_draft = false,\n      version = version + 1,\n      completed_at = CASE WHEN target_status = 'completed' THEN completion.completion_date ELSE completed_at END\n  WHERE id = request.id;\n\n  INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details)\n    VALUES(request.id,actor.id,event_name,jsonb_build_object(\n      'completion_id',completion.id,\n      'photo_id',photo.id,\n      'signature_md5',CASE WHEN v_sig IS NOT NULL THEN md5(v_sig) ELSE NULL END,\n      'signer_name',CASE WHEN v_sig IS NOT NULL THEN actor.full_name ELSE NULL END,\n      'signed_at',CASE WHEN v_sig IS NOT NULL THEN now() ELSE NULL END,\n      'is_safety_critical',COALESCE(request.is_safety_critical,false),\n      'safety_hold',COALESCE(request.safety_hold,false)\n    ));\n\n  RETURN jsonb_build_object('id',completion.id,'state',target_status,'signature',v_sig);\nEND;\n$function$;","CREATE OR REPLACE FUNCTION public.demo_hub_photo(p_token uuid, p_action text, p_request_id uuid DEFAULT NULL::uuid, p_photo_id uuid DEFAULT NULL::uuid, p_sha256 text DEFAULT NULL::text, p_bytes integer DEFAULT NULL::integer)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nDECLARE\n  actor public.demo_employees%ROWTYPE;\n  request public.demo_work_requests%ROWTYPE;\n  photo public.demo_work_order_photos%ROWTYPE;\n  target uuid;\nBEGIN\n  SELECT * INTO actor FROM public.demo_hub_actor(p_token);\n  IF NOT FOUND THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='28000'; END IF;\n  IF p_action NOT IN ('list','reserve','commit','view') OR p_action IS NULL THEN\n    RAISE EXCEPTION 'Invalid action' USING ERRCODE='22023';\n  END IF;\n  IF p_action IN ('commit','view') THEN\n    SELECT * INTO photo FROM public.demo_work_order_photos WHERE id=p_photo_id AND storage_path IS NOT NULL;\n    IF NOT FOUND THEN RAISE EXCEPTION 'Not found' USING ERRCODE='P0002'; END IF;\n    target := photo.work_request_id;\n  ELSE target := p_request_id; END IF;\n  -- Serialize reservations per order; permission checked before returning any data.\n  SELECT * INTO request FROM public.demo_work_requests WHERE id=target FOR UPDATE;\n  IF NOT FOUND OR (actor.role='manager' OR request.requester_id=actor.id\n      OR request.assigned_to=actor.id\n      OR (actor.role='shop' AND p_action IN ('list','view') AND NOT COALESCE(request.hub_draft,false)\n          AND (\n            (request.status='approved' AND request.assigned_to IS NULL)\n            OR (request.status IN ('approved','assigned','accepted','in_progress','needs_help')\n                AND EXISTS (\n                  SELECT 1 FROM public.demo_work_order_assignments a\n                  WHERE a.work_request_id=request.id AND a.employee_id=actor.id AND a.status='active'\n                ))\n          ))) IS NOT TRUE THEN\n    RAISE EXCEPTION 'Not found' USING ERRCODE='P0002';\n  END IF;\n  IF request.hub_draft AND request.requester_id<>actor.id THEN RAISE EXCEPTION 'Not found' USING ERRCODE='P0002'; END IF;\n  IF p_action IN ('commit','view') THEN\n    SELECT * INTO photo FROM public.demo_work_order_photos WHERE id=p_photo_id;\n  END IF;\n  IF p_action='list' THEN\n    RETURN jsonb_build_object('can_replace',actor.role='manager','can_upload',(request.status NOT IN ('closed','denied','completed','awaiting_verification')\n      AND COALESCE(actor.role='manager' OR request.requester_id=actor.id OR request.assigned_to=actor.id,false)),\n      'can_complete',COALESCE((actor.role='manager' OR request.assigned_to=actor.id)\n        AND (request.status IN ('accepted','in_progress') AND (request.work_kind='completed_without_request' OR request.acknowledged_at IS NOT NULL)) AND (NOT request.hub_draft OR request.work_kind='completed_without_request'),false),\n      'photos',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',id,'file_name',file_name,\n        'photo_type',photo_type,'created_at',created_at,'current',photo_type='problem' OR EXISTS(SELECT FROM public.demo_work_completions c WHERE c.id=demo_work_order_photos.completion_id AND c.revision=request.completion_revision)) ORDER BY created_at,id)\n        FROM public.demo_work_order_photos WHERE work_request_id=target AND upload_state='ready'\n          AND storage_path IS NOT NULL AND superseded_at IS NULL),'[]'::jsonb));\n  END IF;\n  IF p_action='view' THEN\n    IF photo.upload_state <> 'ready' OR (photo.superseded_at IS NOT NULL AND actor.role<>'manager') THEN RAISE EXCEPTION 'Not found' USING ERRCODE='P0002'; END IF;\n    RETURN jsonb_build_object('path',photo.storage_path,'bytes',photo.byte_size,'sha256',photo.sha256);\n  END IF;\n  IF request.status IN ('closed','denied','completed','awaiting_verification') THEN\n    RAISE EXCEPTION 'Order is closed' USING ERRCODE='42501';\n  END IF;\n  IF p_action='reserve' THEN\n    IF p_photo_id IS NULL OR p_sha256 IS NULL OR p_sha256 !~ '^[0-9a-f]{64}$'\n      OR p_bytes IS NULL OR p_bytes < 1 OR p_bytes > 5242880 THEN\n      RAISE EXCEPTION 'Invalid photo' USING ERRCODE='22023';\n    END IF;\n    SELECT * INTO photo FROM public.demo_work_order_photos WHERE id=p_photo_id;\n    IF FOUND THEN\n      IF photo.photo_type<>'problem' OR photo.work_request_id<>target OR photo.uploaded_by IS DISTINCT FROM actor.id\n        OR photo.sha256 IS DISTINCT FROM p_sha256 OR photo.byte_size IS DISTINCT FROM p_bytes THEN\n        RAISE EXCEPTION 'Upload ID conflict' USING ERRCODE='23505';\n      END IF;\n    ELSE\n      IF EXISTS (SELECT FROM public.demo_work_order_photos WHERE work_request_id=target AND photo_type='problem' AND sha256=p_sha256 AND upload_state='ready') THEN\n        RAISE EXCEPTION 'This problem photo is already saved on this work order' USING ERRCODE='23505';\n      END IF;\n      IF (SELECT count(*) FROM public.demo_work_order_photos WHERE work_request_id=target) >= 20 THEN\n        RAISE EXCEPTION 'Photo limit reached' USING ERRCODE='54000';\n      END IF;\n      INSERT INTO public.demo_work_order_photos(id,work_request_id,photo_type,file_name,storage_path,\n        uploaded_by,byte_size,sha256,upload_state)\n      VALUES(p_photo_id,target,'problem',p_photo_id::text||'.jpg',\n        'work-orders/'||target::text||'/problem/'||p_photo_id::text||'.jpg',\n        actor.id,p_bytes,p_sha256,'pending') RETURNING * INTO photo;\n    END IF;\n    RETURN jsonb_build_object('id',photo.id,'path',photo.storage_path,'state',photo.upload_state);\n  END IF;\n  IF photo.photo_type<>'problem' OR photo.uploaded_by IS DISTINCT FROM actor.id THEN\n    RAISE EXCEPTION 'Not found' USING ERRCODE='P0002';\n  END IF;\n  IF NOT EXISTS(SELECT FROM storage.objects WHERE bucket_id='hub-work-order-photos'\n      AND name='demo/'||photo.storage_path AND (metadata->>'size')::bigint=photo.byte_size) AND NOT EXISTS(SELECT FROM public.hub_r2_receipts WHERE object_key=photo.storage_path AND byte_size=photo.byte_size AND sha256=photo.sha256) THEN\n    RAISE EXCEPTION 'Upload incomplete' USING ERRCODE='22023';\n  END IF;\n  IF photo.upload_state='pending' THEN\n    UPDATE public.demo_work_order_photos SET upload_state='ready' WHERE id=photo.id;\n    INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details)\n    VALUES(target,actor.id,'problem_photo_added',jsonb_build_object('photo_id',photo.id));\n  END IF;\n  RETURN jsonb_build_object('id',photo.id,'state','ready');\nEND;\n$function$;","CREATE OR REPLACE FUNCTION public.demo_hub_translation_access(p_token uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''\nAS $function$\nbegin\n PERFORM public.demo_hub_actor(p_token);\n return true;\nend $function$;","CREATE OR REPLACE FUNCTION public.demo_hub_translation_cache_get(p_hashes text[])\n RETURNS jsonb\n LANGUAGE sql\n STABLE\n SET search_path TO ''\nAS $function$\n select coalesce(jsonb_agg(jsonb_build_object('source_hash',source_hash,'source_language',source_language,'translation',translation)),'[]'::jsonb) from public.demo_hub_translation_cache where source_hash=any(p_hashes);\n$function$;","CREATE OR REPLACE FUNCTION public.demo_hub_translation_cache_put(p_rows jsonb)\n RETURNS boolean\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nbegin\n if jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows)>20 then raise exception 'Invalid translation batch';end if;\n insert into public.demo_hub_translation_cache(source_hash,source_language,translation)\n select x.source_hash,x.source_language,x.translation from jsonb_to_recordset(p_rows) as x(source_hash text,source_language text,translation text)\n on conflict(source_hash) do nothing;\n return true;\nend $function$;","CREATE OR REPLACE FUNCTION public.demo_hub_inspections(p_token uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nDECLARE\n    actor public.demo_employees%ROWTYPE;\n    op public.demo_hub_operations%ROWTYPE;\n    oid uuid;\n    sub_id uuid;\n    wo_id uuid;\n    result jsonb;\n    ans jsonb;\n    ans_id uuid;\n    defect_count int := 0;\n    r_slug text;\n    r_type text;\n    r_asset_id uuid;\n    r_asset_name text;\n    r_cert text;\n    r_op_name text;\n    r_location text;\n    r_attested boolean;\n    wo_desc text;\nBEGIN\n    -- 1. Authenticate actor via private hub_token\n    SELECT * INTO actor FROM public.demo_employees\n    WHERE hub_token = p_token AND active AND hub_access_enabled AND NOT hub_access_blocked;\n    \n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Access denied' USING ERRCODE = '28000';\n    END IF;\n\n    IF p_data IS NULL OR jsonb_typeof(p_data) <> 'object' THEN\n        RAISE EXCEPTION 'Invalid data payload' USING ERRCODE = '22023';\n    END IF;\n\n    -- ================================================================\n    -- READ ACTIONS\n    -- ================================================================\n\n    -- A. List Catalog Rides\n    IF p_action = 'rides' THEN\n        SELECT COALESCE(jsonb_agg(\n            jsonb_build_object(\n                'id', r.id,\n                'slug', r.slug,\n                'name', r.name,\n                'name_es', r.name_es,\n                'manufacturer', r.manufacturer,\n                'serial_number', r.serial_number,\n                'state_cert_number', r.state_cert_number,\n                'ride_type', r.ride_type,\n                'max_weight_lbs', r.max_weight_lbs,\n                'max_passengers', r.max_passengers,\n                'tub_count', r.tub_count,\n                'passengers_per_tub', r.passengers_per_tub,\n                'height_alone_inches', r.height_alone_inches,\n                'height_with_adult_inches', r.height_with_adult_inches,\n                'speed_rpm', r.speed_rpm,\n                'wind_limit_mph', r.wind_limit_mph,\n                'supported_frequencies', r.supported_frequencies\n            ) ORDER BY r.name\n        ), '[]'::jsonb) INTO result\n        FROM public.demo_rides r\n        WHERE r.is_active;\n        RETURN result;\n\n    -- B. Operator Certifications\n    ELSIF p_action = 'certifications' THEN\n        SELECT COALESCE(jsonb_agg(\n            jsonb_build_object(\n                'id', c.id,\n                'employee_name', c.employee_name,\n                'ride_slug', c.ride_slug,\n                'is_certified', c.is_certified,\n                'certified_date', c.certified_date,\n                'certifying_supervisor', c.certifying_supervisor\n            ) ORDER BY c.employee_name, c.ride_slug\n        ), '[]'::jsonb) INTO result\n        FROM public.demo_ride_operator_certifications c\n        WHERE (p_data->>'ride_slug' IS NULL OR c.ride_slug = p_data->>'ride_slug')\n          AND (p_data->>'employee_name' IS NULL OR lower(c.employee_name) = lower(p_data->>'employee_name'));\n        RETURN result;\n\n    -- C. Inspection Submissions History\n    ELSIF p_action = 'submissions' THEN\n        SELECT COALESCE(jsonb_agg(\n            jsonb_build_object(\n                'id', s.id,\n                'created_at', s.created_at,\n                'completed_at', s.completed_at,\n                'inspection_type', s.inspection_type,\n                'asset_id', s.asset_id,\n                'asset_name', s.asset_name,\n                'state_cert_number', s.state_cert_number,\n                'operator_id', s.operator_id,\n                'operator_printed_name', s.operator_printed_name,\n                'location_spot', s.location_spot,\n                'empty_cycles_attested', s.empty_cycles_attested,\n                'supervisor_printed_name', s.supervisor_printed_name,\n                'supervisor_verified_at', s.supervisor_verified_at,\n                'status', s.status,\n                'defects_count', s.defects_count\n            ) ORDER BY s.created_at DESC\n        ), '[]'::jsonb) INTO result\n        FROM (\n            SELECT * FROM public.demo_ride_inspection_submissions s\n            WHERE (p_data->>'asset_name' IS NULL OR lower(s.asset_name) = lower(p_data->>'asset_name'))\n              AND (p_data->>'status' IS NULL OR s.status = p_data->>'status')\n              AND (p_data->>'inspection_type' IS NULL OR s.inspection_type = p_data->>'inspection_type')\n              AND (actor.role = 'manager' OR s.operator_id = actor.id OR s.operator_printed_name = actor.full_name)\n            LIMIT COALESCE((p_data->>'limit')::int, 50)\n            OFFSET COALESCE((p_data->>'offset')::int, 0)\n        ) s;\n        RETURN result;\n\n    -- D. Fleet Defects List\n    ELSIF p_action = 'defects' THEN\n        SELECT COALESCE(jsonb_agg(\n            jsonb_build_object(\n                'id', d.id,\n                'submission_id', d.submission_id,\n                'asset_id', d.asset_id,\n                'asset_name', d.asset_name,\n                'item_number', d.item_number,\n                'description_en', d.description_en,\n                'operator_notes', d.operator_notes,\n                'photo_url', d.photo_url,\n                'status', d.status,\n                'bridged_work_order_id', d.bridged_work_order_id,\n                'created_at', d.created_at\n            ) ORDER BY d.created_at DESC\n        ), '[]'::jsonb) INTO result\n        FROM public.demo_ride_defects d\n        WHERE (p_data->>'status' IS NULL OR d.status = p_data->>'status')\n          AND (p_data->>'asset_name' IS NULL OR lower(d.asset_name) = lower(p_data->>'asset_name'));\n        RETURN result;\n    END IF;\n\n    -- ================================================================\n    -- MUTATION ACTIONS (Idempotent via hub_operations)\n    -- ================================================================\n    IF p_action NOT IN ('submit', 'verify') THEN\n        RAISE EXCEPTION 'Invalid action' USING ERRCODE = '22023';\n    END IF;\n\n    oid := (p_data->>'operation_id')::uuid;\n    IF oid IS NULL THEN\n        RAISE EXCEPTION 'Operation ID required' USING ERRCODE = '22023';\n    END IF;\n\n    PERFORM pg_advisory_xact_lock(hashtextextended(actor.id::text || oid::text, 0));\n\n    SELECT * INTO op FROM public.demo_hub_operations WHERE actor_id = actor.id AND operation_id = oid;\n    IF FOUND THEN\n        IF op.action <> p_action OR op.input <> p_data THEN\n            RAISE EXCEPTION 'Retry payload changed' USING ERRCODE = '23505';\n        END IF;\n        RETURN op.result;\n    END IF;\n\n    -- 1. SUBMIT INSPECTION\n    IF p_action = 'submit' THEN\n        r_type := p_data->>'inspection_type';\n        r_asset_name := btrim(COALESCE(p_data->>'asset_name', ''));\n        r_cert := p_data->>'state_cert_number';\n        r_op_name := btrim(COALESCE(p_data->>'operator_printed_name', actor.full_name));\n        r_location := btrim(COALESCE(p_data->>'location_spot', 'Main Lot'));\n        r_attested := COALESCE((p_data->>'empty_cycles_attested')::boolean, false);\n\n        IF r_type NOT IN ('daily', 'weekly', 'monthly', 'semi_annual', 'annual', 'reinspection') THEN\n            RAISE EXCEPTION 'Invalid inspection type' USING ERRCODE = '22023';\n        END IF;\n\n        IF length(r_asset_name) < 2 THEN\n            RAISE EXCEPTION 'Asset name required' USING ERRCODE = '22023';\n        END IF;\n\n        -- ASTM F770-22 Section 4.1 mandatory pre-operation check\n        IF NOT r_attested THEN\n            RAISE EXCEPTION 'ASTM F770 requirement: 3 empty test cycles must be attested before passenger operation' USING ERRCODE = '22023';\n        END IF;\n\n        -- Inspection records stand alone; do not resolve maintenance asset IDs.\n        r_asset_id := NULL;\n\n        sub_id := COALESCE((p_data->>'submission_id')::uuid, gen_random_uuid());\n\n        -- Count defects in answers array\n        IF p_data->'answers' IS NOT NULL AND jsonb_typeof(p_data->'answers') = 'array' THEN\n            SELECT count(*) INTO defect_count\n            FROM jsonb_array_elements(p_data->'answers') elem\n            WHERE elem->>'response' = 'needs_repair';\n        END IF;\n\n        -- Insert submission header\n        INSERT INTO public.demo_ride_inspection_submissions (\n            id, inspection_type, asset_id, asset_name, state_cert_number,\n            operator_id, operator_printed_name, location_spot,\n            empty_cycles_attested, status, defects_count, completed_at\n        ) VALUES (\n            sub_id, r_type, r_asset_id, r_asset_name, r_cert,\n            actor.id, r_op_name, r_location,\n            r_attested, CASE WHEN defect_count > 0 THEN 'defect_flagged' ELSE 'submitted' END,\n            defect_count, now()\n        );\n\n        -- Ride inspections are independent: never bridge to maintenance.\n        wo_id := NULL;\n\n        -- Insert individual checklist answers\n        IF p_data->'answers' IS NOT NULL AND jsonb_typeof(p_data->'answers') = 'array' THEN\n            FOR ans IN SELECT * FROM jsonb_array_elements(p_data->'answers')\n            LOOP\n                ans_id := gen_random_uuid();\n                INSERT INTO public.demo_ride_inspection_answers (\n                    id, submission_id, item_id, item_order, item_number,\n                    item_description_en, item_description_es, response, defect_notes, photo_url\n                ) VALUES (\n                    ans_id, sub_id,\n                    COALESCE(ans->>'item_id', 'item_' || (ans->>'item_order')),\n                    COALESCE((ans->>'item_order')::int, 1),\n                    COALESCE(ans->>'item_number', '1'),\n                    COALESCE(ans->>'item_description_en', 'Item description'),\n                    COALESCE(ans->>'item_description_es', ans->>'item_description_en', 'Descripción'),\n                    ans->>'response',\n                    ans->>'defect_notes',\n                    ans->>'photo_url'\n                );\n\n                -- Flag to ride_defects table\n                IF ans->>'response' = 'needs_repair' THEN\n                    INSERT INTO public.demo_ride_defects (\n                        submission_id, answer_id, asset_id, asset_name,\n                        item_number, description_en, operator_notes, photo_url,\n                        status, bridged_work_order_id\n                    ) VALUES (\n                        sub_id, ans_id, r_asset_id, r_asset_name,\n                        COALESCE(ans->>'item_number', '1'),\n                        COALESCE(ans->>'item_description_en', 'Defect item'),\n                        COALESCE(ans->>'defect_notes', 'Needs repair'),\n                        ans->>'photo_url',\n                        CASE WHEN wo_id IS NOT NULL THEN 'bridged_to_maintenance' ELSE 'open' END,\n                        wo_id\n                    );\n                END IF;\n            END LOOP;\n        END IF;\n\n        result := jsonb_build_object(\n            'id', sub_id,\n            'status', CASE WHEN defect_count > 0 THEN 'defect_flagged' ELSE 'submitted' END,\n            'defects_count', defect_count,\n            'bridged_work_order_id', wo_id\n        );\n\n    -- 2. VERIFY INSPECTION (Supervisor Sign-off)\n    ELSIF p_action = 'verify' THEN\n        IF actor.role NOT IN ('manager', 'shop') THEN\n            RAISE EXCEPTION 'Supervisor access required' USING ERRCODE = '42501';\n        END IF;\n\n        sub_id := (p_data->>'submission_id')::uuid;\n        IF sub_id IS NULL THEN\n            RAISE EXCEPTION 'Submission ID required' USING ERRCODE = '22023';\n        END IF;\n\n        UPDATE public.demo_ride_inspection_submissions\n        SET supervisor_id = actor.id,\n            supervisor_printed_name = actor.full_name,\n            supervisor_verified_at = now(),\n            supervisor_notes = p_data->>'supervisor_notes',\n            status = 'verified'\n        WHERE id = sub_id;\n\n        IF NOT FOUND THEN\n            RAISE EXCEPTION 'Submission not found' USING ERRCODE = 'P0002';\n        END IF;\n\n        result := jsonb_build_object('id', sub_id, 'status', 'verified');\n    END IF;\n\n    -- Record idempotent operation\n    INSERT INTO public.demo_hub_operations (actor_id, operation_id, action, input, result)\n    VALUES (actor.id, oid, p_action, p_data, result);\n\n    RETURN result;\nEND;\n$function$;","CREATE OR REPLACE FUNCTION public.demo_hub_workflow(p_token uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nDECLARE \n  actor public.demo_employees%ROWTYPE; \n  emp public.demo_employees%ROWTYPE; \n  r public.demo_work_requests%ROWTYPE; \n  part public.demo_hub_parts%ROWTYPE; \n  op public.demo_hub_operations%ROWTYPE; \n  result jsonb; \n  rid uuid; \n  oid uuid; \n  target uuid; \n  next_state text; \n  description text; \n  kind text; \n  d date;\n  v_self_assign_enabled boolean;\n  v_is_safety boolean;\n  v_is_test boolean;\n  v_role text;\n  v_hold boolean;\n  v_passed boolean;\n  v_mgr_sig text;\n  v_notes text;\n  v_crew_sig text;\n  v_crew_notes text;\n  v_assignment public.demo_work_order_assignments%ROWTYPE;\n  v_contribution_id uuid;\n  v_safety_release_enabled boolean;\n  v_stepup_id uuid;\n  v_asset public.demo_assets%ROWTYPE;\n  v_photo_reason text;\nBEGIN\n SELECT * INTO actor FROM public.demo_hub_actor(p_token);\n IF NOT FOUND OR actor.id IS NULL THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='28000'; END IF;\n \n -- Feature flag check (defaults to false)\n v_self_assign_enabled := COALESCE((SELECT enabled FROM public.demo_hub_feature_flags WHERE feature = 'shop_self_assignment'), false);\n v_safety_release_enabled := COALESCE((SELECT enabled FROM public.demo_hub_feature_flags WHERE feature='safety_release_workflow'),false);\n\n -- Restricted manager approval permission check\n IF p_action='approve' AND (actor.role<>'manager' OR NOT actor.hub_approval_enabled) THEN \n   RAISE EXCEPTION 'Pilot approval restricted' USING ERRCODE='42501'; \n END IF;\n\n IF p_data IS NULL OR jsonb_typeof(p_data)<>'object' THEN RAISE EXCEPTION 'Invalid data' USING ERRCODE='22023'; END IF;\n\n -- Preserve employee invitation workflows\n IF p_action IN ('invitation_list','invitation_send') THEN \n   IF p_action='invitation_list' THEN RETURN '[]'::jsonb; END IF; RAISE EXCEPTION 'Company Slack is not connected. Use Employee access links to invite your team.' USING ERRCODE='22023'; \n END IF;\n\n IF p_action='assets' THEN\n  IF length(btrim(COALESCE(p_data->>'query','')))<2 THEN RETURN '[]'::jsonb; END IF;\n  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',a.id,'name',a.asset_name,'number',a.asset_number)),'[]'::jsonb) INTO result FROM (SELECT id,asset_name,asset_number FROM public.demo_assets WHERE active AND (strpos(lower(asset_name),lower(left(btrim(p_data->>'query'),100)))>0 OR strpos(lower(COALESCE(asset_number,'')),lower(left(btrim(p_data->>'query'),100)))>0) ORDER BY asset_name,id LIMIT 20) a; RETURN result;\n ELSIF p_action='drafts' THEN\n  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',w.id,'asset_id',w.asset_id,'asset',a.asset_name,'description',w.description,'kind',w.work_kind,'date',w.work_date,'is_safety_critical',COALESCE(w.is_safety_critical,false)) ORDER BY w.created_at DESC),'[]'::jsonb) INTO result FROM public.demo_work_requests w LEFT JOIN public.demo_assets a ON a.id=w.asset_id WHERE w.requester_id=actor.id AND w.hub_draft; RETURN result;\n ELSIF p_action='assignees' THEN\n  IF actor.role<>'manager' THEN RAISE EXCEPTION 'Manager required' USING ERRCODE='42501'; END IF;\n  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'name',full_name) ORDER BY full_name,id),'[]'::jsonb) INTO result FROM public.demo_employees WHERE active AND hub_access_enabled AND NOT hub_access_blocked AND role IN ('employee','shop','manager'); RETURN result;\n ELSIF p_action='employees' THEN\n  IF actor.role<>'manager' THEN RAISE EXCEPTION 'Manager required' USING ERRCODE='42501'; END IF;\n  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'name',full_name,'role',role,'active',active,'enabled',hub_access_enabled AND NOT hub_access_blocked,'version',hub_access_version) ORDER BY full_name,id),'[]'::jsonb) INTO result FROM public.demo_employees; RETURN result;\n ELSIF p_action='link' THEN\n  IF actor.role<>'manager' THEN RAISE EXCEPTION 'Manager required' USING ERRCODE='42501'; END IF;\n  SELECT * INTO emp FROM public.demo_employees WHERE id=(p_data->>'id')::uuid AND active AND hub_access_enabled AND NOT hub_access_blocked;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Not found' USING ERRCODE='P0002'; END IF;\n  IF emp.hub_approval_enabled AND actor.id<>emp.id AND NOT actor.hub_approval_enabled THEN RAISE EXCEPTION 'Approver personal link is private' USING ERRCODE='42501'; END IF;\n  INSERT INTO public.demo_hub_access_events(actor_id,employee_id,action) VALUES(actor.id,emp.id,'link_viewed');\n  RETURN jsonb_build_object('token',emp.hub_token);\n ELSIF p_action='health' THEN\n  IF actor.role<>'manager' THEN RAISE EXCEPTION 'Manager required' USING ERRCODE='42501'; END IF;\n  RETURN public.demo_hub_health(p_token);\n ELSIF p_action='history' THEN\n  IF actor.role<>'manager' THEN RAISE EXCEPTION 'Manager required' USING ERRCODE='42501'; END IF;\n  SELECT * INTO r FROM public.demo_work_requests WHERE id=(p_data->>'id')::uuid AND NOT hub_draft;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Not found' USING ERRCODE='P0002'; END IF;\n  RETURN jsonb_build_object('events',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',e.id,'type',e.event_type,'at',e.created_at,'actor',a.full_name,'details',e.details) ORDER BY e.created_at,e.id) FROM public.demo_work_order_events e LEFT JOIN public.demo_employees a ON a.id=e.actor_employee_id WHERE e.work_request_id=r.id),'[]'::jsonb),'archived_photos',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',id,'photo_type',photo_type,'replaced_at',superseded_at)) FROM public.demo_work_order_photos WHERE work_request_id=r.id AND superseded_at IS NOT NULL),'[]'::jsonb));\n ELSIF p_action='pickups' THEN\n  -- A pickup assignment exposes only its own collection details, never job access.\n  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',p.id,'description',p.description,'quantity',p.quantity,\n    'part_number',p.part_number,'state',p.state,'version',p.version,'pickup_store',p.pickup_store,\n    'pickup_notes',p.pickup_notes,'order_number',w.work_order_number,'asset',a.asset_name) ORDER BY p.created_at DESC,p.id),'[]'::jsonb)\n  INTO result FROM public.demo_hub_parts p LEFT JOIN public.demo_work_requests w ON w.id=p.work_request_id\n  LEFT JOIN public.demo_assets a ON a.id=w.asset_id\n  WHERE p.pickup_employee_id=actor.id AND p.procurement_method='local'\n    AND p.state IN ('approved','received','installed') AND (p.work_request_id IS NULL OR (NOT w.hub_draft\n      AND (p.state IN ('received','installed') OR w.status IN ('approved','assigned','accepted','in_progress','needs_help'))));\n  RETURN result;\n ELSIF p_action='parts' THEN\n  SELECT COALESCE(jsonb_agg(to_jsonb(p)||jsonb_build_object('requester',e.full_name,'order_number',w.work_order_number,'asset',a.asset_name,'pickup_employee',pe.full_name) ORDER BY p.created_at DESC),'[]'::jsonb) INTO result FROM public.demo_hub_parts p LEFT JOIN public.demo_work_requests w ON w.id=p.work_request_id LEFT JOIN public.demo_employees e ON e.id=p.requested_by LEFT JOIN public.demo_assets a ON a.id=w.asset_id LEFT JOIN public.demo_employees pe ON pe.id=p.pickup_employee_id WHERE (p.work_request_id IS NULL OR NOT w.hub_draft) AND (actor.role='manager' OR w.assigned_to=actor.id OR EXISTS (SELECT 1 FROM public.demo_work_order_assignments woa WHERE woa.work_request_id = w.id AND woa.employee_id = actor.id AND woa.status = 'active') OR (actor.role='shop' AND p.work_request_id IS NULL AND p.requested_by=actor.id)); RETURN result;\n END IF;\n\n -- Validate action names\n IF p_action NOT IN ('asset_create','create','publish','approve','deny','accept','start','part_create','supply_create','part_update','part_pickup','part_stock','pickup_received','access_disable','access_enable','access_rotate','need_help','reassign','reopen','correct','schedule','verify','claim','join','leave','contribute','prioritize','safety_hold') OR p_action IS NULL THEN \n   RAISE EXCEPTION 'Invalid action' USING ERRCODE='22023'; \n END IF;\n\n -- Feature flag guard for new shop self-assignment actions\n IF p_action IN ('claim','join','leave','contribute') THEN\n  SELECT is_test INTO v_is_test FROM public.demo_work_requests WHERE id = (p_data->>'id')::uuid;\n  v_self_assign_enabled := COALESCE((\n    SELECT CASE WHEN COALESCE(v_is_test, false) THEN (enabled OR test_enabled) ELSE enabled END \n    FROM public.demo_hub_feature_flags WHERE feature = 'shop_self_assignment'\n  ), false);\n  IF NOT v_self_assign_enabled THEN\n    RAISE EXCEPTION 'Self-assignment feature is not enabled' USING ERRCODE='42501';\n  END IF;\n END IF;\n\n oid:=(p_data->>'operation_id')::uuid;\n IF oid IS NULL THEN RAISE EXCEPTION 'Operation required' USING ERRCODE='22023'; END IF;\n PERFORM pg_advisory_xact_lock(hashtextextended(actor.id::text||oid::text,0));\n SELECT * INTO op FROM public.demo_hub_operations WHERE actor_id=actor.id AND operation_id=oid;\n IF FOUND THEN\n  IF op.action<>p_action OR op.input<>p_data THEN RAISE EXCEPTION 'Retry changed' USING ERRCODE='23505'; END IF;\n  RETURN op.result;\n END IF;\n\n IF p_action LIKE 'access_%' THEN\n  IF actor.role<>'manager' THEN RAISE EXCEPTION 'Manager required' USING ERRCODE='42501'; END IF;\n  SELECT * INTO emp FROM public.demo_employees WHERE id=(p_data->>'id')::uuid FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Not found' USING ERRCODE='P0002'; END IF;\n  IF emp.id=actor.id THEN RAISE EXCEPTION 'Ask another manager to change your link' USING ERRCODE='42501'; END IF;\n  IF emp.hub_access_version IS DISTINCT FROM (p_data->>'version')::int THEN RAISE EXCEPTION 'Refresh required' USING ERRCODE='PT409'; END IF;\n  IF p_action<>'access_disable' AND NOT emp.active THEN RAISE EXCEPTION 'Inactive employee' USING ERRCODE='42501'; END IF;\n  UPDATE public.demo_employees SET hub_access_blocked=CASE WHEN p_action='access_disable' THEN true WHEN p_action='access_enable' THEN false ELSE hub_access_blocked END,\n   hub_access_enabled=CASE WHEN p_action='access_enable' THEN true ELSE hub_access_enabled END,\n   hub_token=CASE WHEN p_action IN ('access_rotate','access_enable') THEN gen_random_uuid() ELSE hub_token END,hub_access_version=hub_access_version+1 WHERE id=emp.id;\n  INSERT INTO public.demo_hub_access_events(actor_id,employee_id,action) VALUES(actor.id,emp.id,p_action);\n  result:=jsonb_build_object('id',emp.id);\n\n ELSIF p_action='asset_create' THEN\n  IF NOT v_self_assign_enabled THEN RAISE EXCEPTION 'Asset entry not enabled' USING ERRCODE='42501'; END IF;\n  description:=regexp_replace(btrim(COALESCE(p_data->>'name','')),'[[:space:]]+',' ','g');\n  IF length(description) NOT BETWEEN 2 AND 120 OR description ~ '[[:cntrl:]]' THEN\n    RAISE EXCEPTION 'Asset name required' USING ERRCODE='22023'; END IF;\n  -- Serialize equivalent names without adding a unique constraint to legacy data.\n  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(lower(description)));\n  SELECT * INTO v_asset FROM public.demo_assets\n  WHERE lower(regexp_replace(btrim(asset_name),'[[:space:]]+',' ','g'))=lower(description)\n  ORDER BY active DESC,id LIMIT 1;\n  IF FOUND THEN\n    IF NOT v_asset.active THEN RAISE EXCEPTION 'Existing inactive asset requires manager review' USING ERRCODE='42501'; END IF;\n    result:=jsonb_build_object('id',v_asset.id,'name',v_asset.asset_name,'created',false);\n  ELSE\n    INSERT INTO public.demo_assets(asset_name,active) VALUES(description,true) RETURNING * INTO v_asset;\n    result:=jsonb_build_object('id',v_asset.id,'name',v_asset.asset_name,'created',true);\n  END IF;\n ELSIF p_action='pickup_received' THEN\n  -- Lock in the same work-order/part order used by manager procurement actions.\n  SELECT work_request_id INTO rid FROM public.demo_hub_parts WHERE id=(p_data->>'id')::uuid AND pickup_employee_id=actor.id;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Not found' USING ERRCODE='P0002'; END IF;\n  IF rid IS NOT NULL THEN\n    SELECT * INTO r FROM public.demo_work_requests WHERE id=rid FOR UPDATE;\n    IF NOT FOUND OR r.hub_draft OR r.status NOT IN ('approved','assigned','accepted','in_progress','needs_help') THEN\n      RAISE EXCEPTION 'Active pickup required' USING ERRCODE='PT409'; END IF;\n  END IF;\n  SELECT * INTO part FROM public.demo_hub_parts WHERE id=(p_data->>'id')::uuid AND pickup_employee_id=actor.id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Not found' USING ERRCODE='P0002'; END IF;\n  IF part.version IS DISTINCT FROM (p_data->>'version')::int THEN RAISE EXCEPTION 'Refresh required' USING ERRCODE='PT409'; END IF;\n  IF part.state<>'approved' OR part.procurement_method IS DISTINCT FROM 'local' THEN RAISE EXCEPTION 'Pending local pickup required' USING ERRCODE='PT409'; END IF;\n  UPDATE public.demo_hub_parts SET state='received',version=version+1,updated_at=now() WHERE id=part.id;\n  IF rid IS NOT NULL THEN\n    INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details)\n    VALUES(rid,actor.id,'parts_received',jsonb_build_object('part_id',part.id,'pickup_employee_id',actor.id));\n  END IF;\n  result:=jsonb_build_object('id',part.id,'state','received');\n\n ELSIF p_action='supply_create' THEN\n  IF actor.role NOT IN ('shop','manager') THEN RAISE EXCEPTION 'Shop required' USING ERRCODE='42501'; END IF;\n  description:=btrim(p_data->>'description');\n  IF description IS NULL OR length(description)<1 OR length(description)>1000 OR COALESCE((p_data->>'quantity')::int,0) NOT BETWEEN 1 AND 10000 OR length(btrim(COALESCE(p_data->>'reason','')))<3 OR length(p_data->>'reason')>2000 OR length(COALESCE(p_data->>'part_number',''))>200 OR length(COALESCE(p_data->>'supplier',''))>500 THEN RAISE EXCEPTION 'Supply details required' USING ERRCODE='22023'; END IF;\n  INSERT INTO public.demo_hub_parts(id,requested_by,description,quantity,part_number,supplier,reason) VALUES(oid,actor.id,description,(p_data->>'quantity')::int,COALESCE(p_data->>'part_number',''),COALESCE(p_data->>'supplier',''),p_data->>'reason');\n  result:=jsonb_build_object('id',oid);\n\n ELSIF p_action='create' THEN\n  kind:=p_data->>'kind'; description:=p_data->>'description'; rid:=(p_data->>'id')::uuid;\n  IF kind IS NULL OR kind NOT IN ('requested','completed_without_request') OR rid IS NULL OR description IS NULL OR length(btrim(description))<10 OR length(description)>4000 THEN RAISE EXCEPTION 'Details required' USING ERRCODE='22023'; END IF;\n  IF kind='completed_without_request' AND actor.role NOT IN ('manager','shop') THEN RAISE EXCEPTION 'Shop required' USING ERRCODE='42501'; END IF;\n  IF NOT EXISTS(SELECT FROM public.demo_assets WHERE id=(p_data->>'asset_id')::uuid AND active) THEN RAISE EXCEPTION 'Active equipment required' USING ERRCODE='22023'; END IF;\n  IF (SELECT count(*) FROM public.demo_work_requests WHERE requester_id=actor.id AND hub_draft)>=20 THEN RAISE EXCEPTION 'Finish an existing draft first' USING ERRCODE='54000'; END IF;\n  IF kind='completed_without_request' THEN d:=(p_data->>'date')::date; IF d IS NULL OR d>current_date THEN RAISE EXCEPTION 'Completion date required' USING ERRCODE='22023'; END IF; END IF;\n  v_is_safety := COALESCE((p_data->>'is_safety_critical')::boolean, false);\n  v_is_test := COALESCE((p_data->>'is_test')::boolean, false);\n\n  -- Blocker 4: Protect is_test from ordinary user input and unconfigured environments\n  IF v_is_test AND actor.role NOT IN ('manager','shop') THEN\n    RAISE EXCEPTION 'Ordinary users cannot create test work requests' USING ERRCODE='42501';\n  END IF;\n  IF v_is_test AND NOT COALESCE((SELECT test_enabled FROM public.demo_hub_feature_flags WHERE feature = 'shop_self_assignment'), false) THEN\n    RAISE EXCEPTION 'Test jobs are disabled in live environment' USING ERRCODE='42501';\n  END IF;\n\n  -- Blocker 1: Determine self-assignment flag for this request\n  v_self_assign_enabled := COALESCE((\n    SELECT CASE WHEN v_is_test THEN (enabled OR test_enabled) ELSE enabled END \n    FROM public.demo_hub_feature_flags WHERE feature = 'shop_self_assignment'\n  ), false);\n\n  -- Blocker 1: When self-assignment is disabled, preserve production default (true)\n  -- When self-assignment is enabled, only safety-critical work requires manager verification\n  INSERT INTO public.demo_work_requests(id,requester_id,asset_id,description,status,assigned_to,hub_draft,work_kind,work_date,is_safety_critical,safety_hold,requires_verification,is_test)\n   VALUES(rid,actor.id,(p_data->>'asset_id')::uuid,description,CASE WHEN kind='requested' THEN 'submitted' ELSE 'in_progress' END,CASE WHEN kind='completed_without_request' THEN actor.id ELSE NULL END,true,kind,d,v_is_safety,v_is_safety,CASE WHEN v_self_assign_enabled THEN v_is_safety ELSE true END,v_is_test) RETURNING * INTO r;\n   -- A preventive job entered without a prior request is already led by its\n   -- authenticated creator; keep the crew assignment table consistent.\n   IF v_self_assign_enabled AND kind='completed_without_request' THEN\n     INSERT INTO public.demo_work_order_assignments(work_request_id,employee_id,assignment_role,status)\n     VALUES(r.id,actor.id,'lead','active');\n   END IF;\n   result:=jsonb_build_object('id',r.id,'number',r.work_order_number,'is_test',r.is_test);\n\n ELSE\n  IF p_action IN ('part_update','part_pickup','part_stock') THEN\n   SELECT work_request_id INTO rid FROM public.demo_hub_parts WHERE id=(p_data->>'id')::uuid;\n  ELSE rid:=(p_data->>'id')::uuid; END IF;\n  IF rid IS NULL AND p_action IN ('part_update','part_pickup','part_stock') THEN\n   SELECT * INTO part FROM public.demo_hub_parts WHERE id=(p_data->>'id')::uuid AND work_request_id IS NULL FOR UPDATE;\n   IF NOT FOUND OR (actor.role='manager' OR (actor.role='shop' AND part.requested_by=actor.id)) IS NOT TRUE THEN RAISE EXCEPTION 'Not found' USING ERRCODE='P0002'; END IF;\n  ELSE\n   SELECT * INTO r FROM public.demo_work_requests WHERE id=rid FOR UPDATE;\n   IF NOT FOUND THEN\n     RAISE EXCEPTION 'Not found' USING ERRCODE='P0002';\n   END IF;\n   v_self_assign_enabled := COALESCE((\n     SELECT CASE WHEN COALESCE(r.is_test, false) THEN (enabled OR test_enabled) ELSE enabled END \n     FROM public.demo_hub_feature_flags WHERE feature = 'shop_self_assignment'\n   ), false);\n   IF (\n     actor.role='manager' \n     OR r.requester_id=actor.id \n     OR r.assigned_to=actor.id \n     OR (v_self_assign_enabled AND actor.role='shop' AND (\n       r.status IN ('approved','assigned','accepted','in_progress')\n       OR EXISTS(SELECT 1 FROM public.demo_work_order_assignments woa WHERE woa.work_request_id=r.id AND woa.employee_id=actor.id)\n     ))\n   ) IS NOT TRUE THEN \n     RAISE EXCEPTION 'Not found' USING ERRCODE='P0002'; \n   END IF;\n  END IF;\n\n  IF p_action IN ('schedule','verify') THEN\n   IF actor.role<>'manager' THEN RAISE EXCEPTION 'Manager required' USING ERRCODE='42501'; END IF;\n   IF r.hub_draft OR r.version IS DISTINCT FROM (p_data->>'version')::int THEN RAISE EXCEPTION 'Refresh required' USING ERRCODE='PT409'; END IF;\n   description:=btrim(p_data->>'reason');\n   IF description IS NULL OR length(description)<3 OR length(description)>2000 THEN RAISE EXCEPTION 'Reason required' USING ERRCODE='22023'; END IF;\n   v_notes:=description;\n   IF p_action='schedule' THEN\n    IF r.status IN('completed','closed','denied','awaiting_verification') THEN RAISE EXCEPTION 'Active work required' USING ERRCODE='PT409';END IF;\n    d:=NULLIF(p_data->>'due_date','')::date;\n    IF NOT (p_data ? 'requires_verification') OR jsonb_typeof(p_data->'requires_verification')<>'boolean' OR (d IS NOT NULL AND d<(now()at time zone 'America/Los_Angeles')::date) THEN RAISE EXCEPTION 'Check due date and inspection requirement' USING ERRCODE='22023';END IF;\n    IF (r.is_safety_critical OR r.safety_hold) AND NOT (p_data->>'requires_verification')::boolean THEN\n      RAISE EXCEPTION 'Safety-critical work orders require inspection' USING ERRCODE='42501';\n    END IF;\n    UPDATE public.demo_work_requests SET due_date=d,requires_verification=(p_data->>'requires_verification')::boolean,version=version+1 WHERE id=r.id;\n    INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details) VALUES(r.id,actor.id,'schedule',jsonb_build_object('reason',description,'before',jsonb_build_object('due_date',r.due_date,'requires_verification',r.requires_verification),'after',jsonb_build_object('due_date',d,'requires_verification',(p_data->>'requires_verification')::boolean)));\n    result:=jsonb_build_object('id',r.id);\n   ELSE\n    -- VERIFY (Manager Inspection Sign-off)\n    -- Only an explicitly authorized manager may inspect, sign off and close safety-critical work.\n    IF NOT actor.hub_approval_enabled THEN RAISE EXCEPTION 'Pilot approval restricted' USING ERRCODE='42501'; END IF;\n    IF r.status<>'awaiting_verification' THEN RAISE EXCEPTION 'Inspection is not pending' USING ERRCODE='PT409';END IF;\n    IF NOT EXISTS(SELECT FROM public.demo_work_completions c JOIN public.demo_work_order_photos p ON p.completion_id=c.id AND p.upload_state='ready' AND p.superseded_at IS NULL WHERE c.work_request_id=r.id AND c.revision=r.completion_revision) THEN RAISE EXCEPTION 'Completion notes and photo required' USING ERRCODE='22023';END IF;\n    IF EXISTS(SELECT FROM public.demo_work_completions WHERE work_request_id=r.id AND revision=r.completion_revision AND completed_by=actor.id) OR EXISTS(SELECT FROM public.demo_work_order_contribution_signatures WHERE work_request_id=r.id AND completion_revision=r.completion_revision AND employee_id=actor.id) THEN RAISE EXCEPTION 'Another manager must inspect your work' USING ERRCODE='42501';END IF;\n    \n    -- Explicit pass/fail inspection decision:\n    -- Requirement 1: Mandated for safety-critical or safety-held work regardless of feature flag.\n    -- Preserves legacy behavior (defaulting to passed) for existing noncritical work when self-assignment is disabled.\n    IF p_data ? 'passed' AND jsonb_typeof(p_data->'passed') = 'boolean' THEN\n      v_passed := (p_data->>'passed')::boolean;\n    ELSIF (r.is_safety_critical OR r.safety_hold) OR v_self_assign_enabled THEN\n      RAISE EXCEPTION 'Explicit pass/fail inspection decision required' USING ERRCODE='22023';\n    ELSE\n      -- Legacy behavior for existing noncritical work when self-assignment is disabled: default to passed\n      v_passed := true;\n    END IF;\n    \n    -- Explicit manager electronic signature:\n    -- Requirement 1: Mandated for safety-critical or safety-held work regardless of feature flag.\n    v_mgr_sig := NULLIF(btrim(p_data->>'signature'), '');\n    IF v_mgr_sig IS NOT NULL AND (r.is_safety_critical OR r.safety_hold OR v_self_assign_enabled)\n       AND NOT public.demo_hub_valid_png_signature(v_mgr_sig) THEN\n      RAISE EXCEPTION 'Drawn PNG manager signature required' USING ERRCODE='22023';\n    END IF;\n    IF ((r.is_safety_critical OR r.safety_hold) OR v_self_assign_enabled) AND v_mgr_sig IS NULL THEN\n      RAISE EXCEPTION 'Active electronic signature required' USING ERRCODE='22023';\n    END IF;\n    IF ((r.is_safety_critical OR r.safety_hold) OR v_self_assign_enabled)\n       AND NOT public.demo_hub_signature_name_matches(p_data->>'signer_name',actor.full_name) THEN\n      RAISE EXCEPTION 'Typed manager signer name must match your employee record' USING ERRCODE='22023';\n    END IF;\n\n    -- Requirement 1: Verify that safety-critical or safety-held work has an explicit repair signature recorded on its completion\n    IF (r.is_safety_critical OR r.safety_hold) THEN\n      IF NOT EXISTS (\n        SELECT 1 FROM public.demo_work_completions \n        WHERE work_request_id = r.id \n          AND revision = r.completion_revision \n          AND NULLIF(btrim(signature), '') IS NOT NULL\n      ) THEN\n        RAISE EXCEPTION 'Repair electronic signature required before inspection' USING ERRCODE='22023';\n      END IF;\n    END IF;\n\n    -- Manager personal Hub capability plus current database permissions authorize inspection.\n    -- Signatures, independent inspector, photos, revision and version checks remain above.\n    IF v_passed AND (r.is_safety_critical OR r.safety_hold) AND NOT v_safety_release_enabled THEN\n      RAISE EXCEPTION 'Safety release not enabled. Keep equipment on hold; use existing approved safety process.' USING ERRCODE='42501';\n    END IF;\n\n    IF v_mgr_sig IS NOT NULL AND public.demo_hub_valid_png_signature(v_mgr_sig) THEN\n      INSERT INTO public.demo_work_order_inspection_signatures\n        (work_request_id,employee_id,completion_revision,passed,notes,signature_png,signer_name,stepup_id)\n      VALUES(r.id,actor.id,r.completion_revision,v_passed,v_notes,v_mgr_sig,actor.full_name,v_stepup_id);\n    END IF;\n    IF NOT v_passed THEN\n      -- Failed inspection returns the job to shop for additional repairs\n      UPDATE public.demo_work_requests \n      SET status='in_progress',verified_at=NULL,verified_by=actor.id,verification_notes=v_notes,\n          safety_hold=CASE WHEN r.is_safety_critical OR r.safety_hold THEN true ELSE safety_hold END,\n          verification_signature=NULL,verification_signer_name=NULL,verification_signed_at=NULL,\n          completion_revision=completion_revision+1,version=version+1 \n      WHERE id=r.id;\n      INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details) \n      VALUES(r.id,actor.id,'inspection_failed',jsonb_build_object(\n        'reason',description,\n        'completion_revision',r.completion_revision,\n        'signature_md5',CASE WHEN v_mgr_sig IS NOT NULL THEN md5(v_mgr_sig) ELSE NULL END,\n        'signer_name',CASE WHEN v_mgr_sig IS NOT NULL THEN actor.full_name ELSE NULL END\n      ));\n      result:=jsonb_build_object('id',r.id,'status','in_progress','passed',false);\n    ELSE\n      -- Passed inspection: Sign off, close work order, record electronic signature, and release safety hold\n      IF v_stepup_id IS NOT NULL THEN\n        UPDATE public.demo_hub_manager_stepup_attestations SET consumed_at=now() WHERE id=v_stepup_id;\n      END IF;\n      UPDATE public.demo_work_requests \n      SET status='completed',\n          verified_at=now(),\n          verified_by=actor.id,\n          verification_notes=v_notes,\n          verification_signature=v_mgr_sig,\n          verification_signer_name=CASE WHEN v_mgr_sig IS NOT NULL THEN actor.full_name ELSE NULL END,\n          verification_signed_at=CASE WHEN v_mgr_sig IS NOT NULL THEN now() ELSE NULL END,\n          safety_hold=false,\n          completed_at=COALESCE(completed_at, now()),\n          version=version+1 \n      WHERE id=r.id;\n      INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details) \n      VALUES(r.id,actor.id,'work_verified',jsonb_build_object(\n        'reason',description,\n        'completion_revision',r.completion_revision,\n        'signature_md5',CASE WHEN v_mgr_sig IS NOT NULL THEN md5(v_mgr_sig) ELSE NULL END,\n        'signer_name',CASE WHEN v_mgr_sig IS NOT NULL THEN actor.full_name ELSE NULL END,\n        'safety_hold_released',COALESCE(r.safety_hold,false)\n      ));\n      result:=jsonb_build_object('id',r.id,'status','completed','passed',true,'signature',v_mgr_sig);\n    END IF;\n   END IF;\n\n  ELSIF p_action IN ('need_help','reassign','reopen','correct') THEN\n   IF r.hub_draft OR r.version IS DISTINCT FROM (p_data->>'version')::int THEN RAISE EXCEPTION 'Refresh required' USING ERRCODE='PT409'; END IF;\n   description:=btrim(p_data->>'reason');\n   IF description IS NULL OR length(description)<3 OR length(description)>2000 THEN RAISE EXCEPTION 'Reason required' USING ERRCODE='22023'; END IF;\n   IF p_action='need_help' THEN\n    IF r.assigned_to IS DISTINCT FROM actor.id OR r.status NOT IN ('assigned','accepted','in_progress') THEN RAISE EXCEPTION 'Active assignee required' USING ERRCODE='42501'; END IF;\n    UPDATE public.demo_work_requests SET status='needs_help',help_reason=btrim(p_data->>'reason'),version=version+1 WHERE id=r.id;\n    INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details) VALUES(r.id,actor.id,'need_help',jsonb_build_object('from',r.status,'reason',description));\n   ELSE\n    IF actor.role<>'manager' THEN RAISE EXCEPTION 'Manager required' USING ERRCODE='42501'; END IF;\n    IF p_action IN ('reassign','reopen') THEN\n     IF (p_action='reassign' AND r.status NOT IN ('submitted','approved','assigned','accepted','in_progress','needs_help')) OR (p_action='reopen' AND r.status NOT IN ('completed','closed','denied','awaiting_verification')) THEN RAISE EXCEPTION 'Invalid transition' USING ERRCODE='PT409'; END IF;\n     target:=NULLIF(p_data->>'assignee','')::uuid;\n     IF target IS NULL OR NOT EXISTS(SELECT FROM public.demo_employees WHERE id=target AND active AND hub_access_enabled AND NOT hub_access_blocked) THEN RAISE EXCEPTION 'Active assignee required' USING ERRCODE='22023'; END IF;\n     IF length(COALESCE(p_data->>'notes',''))>4000 THEN RAISE EXCEPTION 'Instructions too long' USING ERRCODE='22023'; END IF;\n     UPDATE public.demo_work_requests SET assigned_to=target,status='assigned',acknowledged_at=NULL,completed_at=NULL,verified_at=NULL,verified_by=NULL,verification_notes=NULL,denial_reason=NULL,help_reason=NULL,\n      shop_instructions=COALESCE(p_data->>'notes',shop_instructions),\n      safety_hold=CASE WHEN r.is_safety_critical THEN true ELSE safety_hold END,\n      requires_verification=CASE WHEN r.is_safety_critical OR r.safety_hold THEN true ELSE requires_verification END,\n      verification_signature=NULL,verification_signer_name=NULL,verification_signed_at=NULL,\n      completion_revision=completion_revision+1,version=version+1 WHERE id=r.id;\n     IF v_self_assign_enabled THEN\n       -- Safely demote existing active lead to assistant before setting target to lead\n       UPDATE public.demo_work_order_assignments\n       SET assignment_role = 'assistant', updated_at = now()\n       WHERE work_request_id = r.id AND status = 'active' AND assignment_role = 'lead' AND employee_id <> target;\n\n       INSERT INTO public.demo_work_order_assignments(work_request_id,employee_id,assignment_role,status,joined_at)\n       VALUES(r.id,target,'lead','active',now())\n       ON CONFLICT (work_request_id, employee_id) WHERE status='active' DO UPDATE SET assignment_role='lead',left_at=NULL;\n     END IF;\n     INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details) VALUES(r.id,actor.id,p_action,jsonb_build_object('from',r.status,'previous_assignee',r.assigned_to,'assignee',target,'reason',description));\n    ELSE\n     -- Correct action: Prevent downgrading safety-critical classification\n     IF r.is_safety_critical AND p_data ? 'is_safety_critical' AND NOT (p_data->>'is_safety_critical')::boolean THEN\n       RAISE EXCEPTION 'Cannot downgrade safety-critical classification' USING ERRCODE='42501';\n     END IF;\n     IF length(btrim(COALESCE(p_data->>'description','')))<10 OR length(p_data->>'description')>4000 OR length(COALESCE(p_data->>'notes',''))>4000 OR length(COALESCE(p_data->>'completion_notes',''))>4000 OR COALESCE(p_data->>'priority','') NOT IN ('low','normal','high','urgent') THEN RAISE EXCEPTION 'Details required' USING ERRCODE='22023'; END IF;\n     IF NOT EXISTS(SELECT FROM public.demo_assets WHERE id=(p_data->>'asset_id')::uuid AND active) THEN RAISE EXCEPTION 'Active equipment required' USING ERRCODE='22023'; END IF;\n     INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details) VALUES(r.id,actor.id,'correct',jsonb_build_object('reason',description,'before',jsonb_build_object('asset_id',r.asset_id,'description',r.description,'priority',r.priority,'instructions',r.shop_instructions),'after',jsonb_build_object('asset_id',p_data->>'asset_id','description',btrim(p_data->>'description'),'priority',p_data->>'priority','instructions',p_data->>'notes')));\n     UPDATE public.demo_work_requests SET asset_id=(p_data->>'asset_id')::uuid,description=btrim(p_data->>'description'),priority=p_data->>'priority',shop_instructions=p_data->>'notes',status=CASE WHEN r.verified_at IS NOT NULL THEN 'awaiting_verification' ELSE status END,\n      safety_hold=CASE WHEN r.is_safety_critical THEN true ELSE safety_hold END,\n      requires_verification=CASE WHEN r.is_safety_critical OR r.safety_hold THEN true ELSE requires_verification END,\n      verified_at=NULL,verified_by=NULL,verification_notes=NULL,\n      verification_signature=NULL,verification_signer_name=NULL,verification_signed_at=NULL,version=version+1 WHERE id=r.id;\n     IF p_data ? 'completion_notes' THEN\n      IF EXISTS(SELECT FROM public.demo_work_completions WHERE work_request_id=r.id AND revision=r.completion_revision AND signature IS NOT NULL AND completion_notes IS DISTINCT FROM btrim(p_data->>'completion_notes')) THEN\n       RAISE EXCEPTION 'Signed repair notes cannot be rewritten; reopen for a new signed repair revision' USING ERRCODE='42501'; END IF;\n      IF length(btrim(p_data->>'completion_notes'))<1 OR NOT EXISTS(SELECT FROM public.demo_work_completions WHERE work_request_id=r.id AND revision=r.completion_revision) THEN RAISE EXCEPTION 'Current completion required' USING ERRCODE='22023'; END IF;\n      INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details)\n       SELECT r.id,actor.id,'completion_corrected',jsonb_build_object('reason',description,'completion_id',id,'before',completion_notes,'after',btrim(p_data->>'completion_notes')) FROM public.demo_work_completions WHERE work_request_id=r.id AND revision=r.completion_revision;\n      UPDATE public.demo_work_completions SET completion_notes=btrim(p_data->>'completion_notes') WHERE work_request_id=r.id AND revision=r.completion_revision;\n     END IF;\n    END IF;\n   END IF;\n   result:=jsonb_build_object('id',r.id);\n\n  ELSIF p_action='publish' THEN\n   IF r.requester_id<>actor.id OR r.work_kind<>'requested' THEN RAISE EXCEPTION 'Owner required' USING ERRCODE='42501'; END IF;\n   IF NOT EXISTS(SELECT FROM public.demo_work_order_photos WHERE work_request_id=r.id AND photo_type='problem' AND upload_state='ready' AND storage_path IS NOT NULL) THEN\n     v_photo_reason:=btrim(COALESCE(p_data->>'photo_unavailable_reason',r.problem_photo_unavailable_reason,''));\n     IF length(v_photo_reason) NOT BETWEEN 10 AND 800 THEN RAISE EXCEPTION 'Photo or an explanation of at least 10 characters required' USING ERRCODE='22023'; END IF;\n     IF r.hub_draft THEN\n       UPDATE public.demo_work_requests SET problem_photo_unavailable_reason=v_photo_reason WHERE id=r.id;\n       INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details)\n       VALUES(r.id,actor.id,'photo_unavailable',jsonb_build_object('reason',v_photo_reason));\n     END IF;\n   END IF;\n   IF r.hub_draft THEN\n     IF v_self_assign_enabled THEN\n       -- Routine maintenance: No manager approval before work begins. Automatically appears on Shop Work Board.\n       -- Safety-critical maintenance: Flagged and applied safety hold; opens for shop repair without routine preapproval.\n       v_is_safety := COALESCE(r.is_safety_critical, false);\n       UPDATE public.demo_work_requests \n       SET hub_draft=false,\n           submission_date=now(),\n           status='approved',\n           assigned_to=NULL,\n           safety_hold=v_is_safety,\n           requires_verification=v_is_safety,\n           version=version+1 \n       WHERE id=r.id;\n       INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details) \n       VALUES(r.id,actor.id,'opened_for_assignment',jsonb_build_object('is_safety_critical',v_is_safety,'safety_hold',v_is_safety));\n       result:=jsonb_build_object('id',r.id,'status','approved','is_safety_critical',v_is_safety,'safety_hold',v_is_safety);\n     ELSE\n       -- Live production workflow preserved: moves to submitted awaiting manager approval\n       UPDATE public.demo_work_requests \n       SET hub_draft=false,\n           submission_date=now(),\n           status='submitted',\n           safety_hold=CASE WHEN COALESCE(r.is_safety_critical,false) THEN true ELSE false END,\n           requires_verification=true,\n           version=version+1 \n       WHERE id=r.id;\n       INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details) \n       VALUES(r.id,actor.id,'submitted',jsonb_build_object('is_safety_critical',COALESCE(r.is_safety_critical,false)));\n       result:=jsonb_build_object('id',r.id,'status','submitted');\n     END IF;\n   ELSE\n     result:=jsonb_build_object('id',r.id,'status',r.status);\n   END IF;\n\n  ELSIF p_action='claim' THEN\n   IF actor.role NOT IN ('shop','manager') THEN RAISE EXCEPTION 'Shop or manager role required' USING ERRCODE='42501'; END IF;\n   -- Authorized shop employees may claim and perform repairs on safety-critical jobs without routine preapproval\n   IF r.assigned_to IS NOT NULL AND r.assigned_to<>actor.id THEN RAISE EXCEPTION 'Job already claimed by another employee' USING ERRCODE='PT409'; END IF;\n   IF r.status NOT IN ('approved','assigned') THEN RAISE EXCEPTION 'Job not available' USING ERRCODE='PT409'; END IF;\n   UPDATE public.demo_work_requests SET assigned_to=actor.id,status='assigned',acknowledged_at=now(),version=version+1 WHERE id=r.id;\n   INSERT INTO public.demo_work_order_assignments(work_request_id,employee_id,assignment_role,status,joined_at)\n   VALUES(r.id,actor.id,'lead','active',now())\n   ON CONFLICT (work_request_id, employee_id) WHERE status='active' DO UPDATE SET assignment_role='lead',left_at=NULL;\n   INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details)\n   VALUES(r.id,actor.id,'job_claimed',jsonb_build_object('lead_id',actor.id,'lead_name',actor.full_name));\n   result:=jsonb_build_object('id',r.id,'role','lead','status','assigned');\n\n  ELSIF p_action='join' THEN\n   IF actor.role NOT IN ('shop','manager') THEN RAISE EXCEPTION 'Shop or manager role required' USING ERRCODE='42501'; END IF;\n   -- Additional crew may join active jobs\n   IF r.hub_draft OR r.status NOT IN ('approved','assigned','accepted','in_progress') THEN RAISE EXCEPTION 'Work order is not open for crew' USING ERRCODE='PT409'; END IF;\n   IF EXISTS(SELECT 1 FROM public.demo_work_order_assignments WHERE work_request_id=r.id AND employee_id=actor.id AND status='active') THEN RAISE EXCEPTION 'Already joined' USING ERRCODE='PT409'; END IF;\n   v_role := CASE WHEN r.assigned_to IS NULL THEN 'lead' ELSE 'assistant' END;\n   INSERT INTO public.demo_work_order_assignments(work_request_id,employee_id,assignment_role,status,joined_at)\n   VALUES(r.id,actor.id,v_role,'active',now());\n   IF r.assigned_to IS NULL THEN \n     UPDATE public.demo_work_requests SET assigned_to=actor.id,status='assigned',acknowledged_at=now(),version=version+1 WHERE id=r.id; \n   END IF;\n   INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details)\n   VALUES(r.id,actor.id,'worker_joined',jsonb_build_object('employee_id',actor.id,'employee_name',actor.full_name,'role',v_role));\n   result:=jsonb_build_object('id',r.id,'role',v_role,'status','active');\n\n  ELSIF p_action='contribute' THEN\n   IF actor.role NOT IN ('employee','shop','manager') THEN RAISE EXCEPTION 'Worker required' USING ERRCODE='42501'; END IF;\n   IF r.hub_draft OR r.status NOT IN ('approved','assigned','accepted','in_progress') THEN RAISE EXCEPTION 'Active work order required' USING ERRCODE='42501'; END IF;\n   SELECT * INTO v_assignment FROM public.demo_work_order_assignments\n   WHERE work_request_id=r.id AND employee_id=actor.id AND status='active' FOR UPDATE;\n   IF NOT FOUND THEN RAISE EXCEPTION 'Join this job before signing contributions' USING ERRCODE='42501'; END IF;\n   v_crew_notes := btrim(p_data->>'work_performed');\n   v_crew_sig := NULLIF(btrim(p_data->>'signature'),'');\n   IF v_crew_notes IS NULL OR length(v_crew_notes) NOT BETWEEN 3 AND 4000\n      OR NOT public.demo_hub_valid_png_signature(v_crew_sig)\n       OR NOT public.demo_hub_signature_name_matches(p_data->>'signer_name',actor.full_name) THEN\n     RAISE EXCEPTION 'Describe your work and actively draw your PNG signature' USING ERRCODE='22023';\n   END IF;\n   INSERT INTO public.demo_work_order_contribution_signatures\n      (work_request_id,assignment_id,employee_id,completion_revision,work_performed,signature_png,signer_name)\n   VALUES(r.id,v_assignment.id,actor.id,r.completion_revision,v_crew_notes,v_crew_sig,actor.full_name)\n   RETURNING id INTO v_contribution_id;\n   UPDATE public.demo_work_order_assignments\n      SET work_performed=v_crew_notes,contribution_signed_at=now(),\n          contribution_revision=r.completion_revision,updated_at=now()\n   WHERE id=v_assignment.id;\n   INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details)\n   VALUES(r.id,actor.id,'crew_contribution_signed',jsonb_build_object(\n      'contribution_id',v_contribution_id,'completion_revision',r.completion_revision,\n      'signer_name',actor.full_name));\n   result:=jsonb_build_object('id',r.id,'contribution_id',v_contribution_id,'status','signed');\n\n  ELSIF p_action='leave' THEN\n   IF r.hub_draft OR r.status NOT IN ('approved','assigned','accepted','in_progress') THEN RAISE EXCEPTION 'Work order is not open for crew' USING ERRCODE='PT409'; END IF;\n   IF actor.role NOT IN ('shop','manager') THEN RAISE EXCEPTION 'Shop or manager role required' USING ERRCODE='42501'; END IF;\n   SELECT * INTO v_assignment FROM public.demo_work_order_assignments\n   WHERE work_request_id=r.id AND employee_id=actor.id AND status='active' FOR UPDATE;\n   IF NOT FOUND THEN RAISE EXCEPTION 'No active assignment' USING ERRCODE='P0002'; END IF;\n   v_crew_notes := NULLIF(btrim(p_data->>'work_performed'),'');\n   v_crew_sig := NULLIF(btrim(p_data->>'signature'),'');\n   IF p_data->>'no_work' = 'true' THEN\n     IF v_crew_notes IS NOT NULL OR v_crew_sig IS NOT NULL OR NULLIF(btrim(p_data->>'signer_name'),'') IS NOT NULL THEN\n       RAISE EXCEPTION 'No-work exit cannot contain a contribution or a signature' USING ERRCODE='22023';\n     END IF;\n   ELSE\n     IF v_crew_notes IS NULL OR length(v_crew_notes) NOT BETWEEN 3 AND 4000\n       OR NOT public.demo_hub_valid_png_signature(v_crew_sig)\n        OR NOT public.demo_hub_signature_name_matches(p_data->>'signer_name',actor.full_name) THEN\n       RAISE EXCEPTION 'Describe and sign your contribution, or explicitly select no work' USING ERRCODE='22023';\n     END IF;\n     INSERT INTO public.demo_work_order_contribution_signatures\n       (work_request_id,assignment_id,employee_id,completion_revision,work_performed,signature_png,signer_name)\n     VALUES(r.id,v_assignment.id,actor.id,r.completion_revision,v_crew_notes,v_crew_sig,actor.full_name)\n     RETURNING id INTO v_contribution_id;\n   END IF;\n   UPDATE public.demo_work_order_assignments\n   SET status='left',left_at=now(),\n       work_performed=COALESCE(v_crew_notes,work_performed),\n       contribution_signed_at=CASE WHEN v_contribution_id IS NOT NULL THEN now() ELSE contribution_signed_at END,\n       contribution_revision=CASE WHEN v_contribution_id IS NOT NULL THEN r.completion_revision ELSE contribution_revision END,\n       updated_at=now()\n   WHERE id=v_assignment.id;\n   IF r.assigned_to=actor.id THEN\n    -- Transfer lead to next active crew member if present\n    SELECT employee_id INTO target FROM public.demo_work_order_assignments \n    WHERE work_request_id=r.id AND status='active' AND employee_id<>actor.id \n    ORDER BY joined_at, id LIMIT 1;\n    IF target IS NOT NULL THEN\n     UPDATE public.demo_work_requests SET assigned_to=target,version=version+1 WHERE id=r.id;\n     UPDATE public.demo_work_order_assignments SET assignment_role='lead' WHERE work_request_id=r.id AND employee_id=target AND status='active';\n    ELSE\n     UPDATE public.demo_work_requests SET assigned_to=NULL,status='approved',version=version+1 WHERE id=r.id;\n    END IF;\n   END IF;\n   INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details)\n   VALUES(r.id,actor.id,'worker_left',jsonb_build_object('employee_id',actor.id,'employee_name',actor.full_name,'contribution_id',v_contribution_id,'no_work',COALESCE((p_data->>'no_work')::boolean,false)));\n   result:=jsonb_build_object('id',r.id,'status','left');\n\n  ELSIF p_action='safety_hold' THEN\n   IF actor.role<>'manager' THEN RAISE EXCEPTION 'Manager required' USING ERRCODE='42501'; END IF;\n   \n   -- Downgrade prevention: Prevent downgrading safety-critical classification\n   IF r.is_safety_critical AND p_data ? 'is_safety_critical' AND NOT (p_data->>'is_safety_critical')::boolean THEN\n     RAISE EXCEPTION 'Cannot downgrade safety-critical classification' USING ERRCODE='42501';\n   END IF;\n\n   -- Escalation to safety-critical by manager\n   IF p_data ? 'is_safety_critical' AND (p_data->>'is_safety_critical')::boolean THEN\n     UPDATE public.demo_work_requests \n     SET is_safety_critical=true,\n         safety_hold=true,\n         requires_verification=true,\n         manager_notes=CASE WHEN p_data->>'reason' IS NOT NULL THEN left(p_data->>'reason',4000) ELSE manager_notes END,\n         version=version+1\n     WHERE id=r.id;\n     INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details)\n     VALUES(r.id,actor.id,'safety_escalated',jsonb_build_object('reason',p_data->>'reason','status',r.status));\n     result:=jsonb_build_object('id',r.id,'is_safety_critical',true,'safety_hold',true);\n   ELSE\n     v_hold := (p_data->>'hold')::boolean;\n     -- Requirement 1: Prevent release based on missing or outdated inspection signatures\n     IF NOT v_hold AND (r.is_safety_critical OR r.safety_hold) THEN\n       RAISE EXCEPTION 'Manual hold release disabled. Signed manager inspection is required.' USING ERRCODE='42501';\n       IF NOT actor.hub_approval_enabled THEN\n         RAISE EXCEPTION 'Pilot approval restricted' USING ERRCODE='42501';\n       END IF;\n       IF r.status<>'completed' \n          OR r.verified_at IS NULL \n          OR r.verified_by IS NULL \n          OR NULLIF(btrim(r.verification_signature), '') IS NULL\n          OR r.verification_signed_at IS NULL\n          OR r.completed_at IS NULL\n          OR r.verification_signed_at < r.completed_at\n          OR r.verified_at < r.completed_at THEN\n         RAISE EXCEPTION 'Safety hold on safety-critical equipment cannot be released without an authorized manager inspection sign-off' USING ERRCODE='42501';\n       END IF;\n     END IF;\n     \n     UPDATE public.demo_work_requests \n     SET safety_hold=v_hold,\n         manager_notes=CASE WHEN p_data->>'reason' IS NOT NULL THEN left(p_data->>'reason',4000) ELSE manager_notes END,\n         version=version+1 \n     WHERE id=r.id;\n     INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details)\n     VALUES(r.id,actor.id,CASE WHEN v_hold THEN 'safety_hold_placed' ELSE 'safety_hold_released' END,\n       jsonb_build_object('reason',p_data->>'reason','status',r.status));\n     result:=jsonb_build_object('id',r.id,'safety_hold',v_hold);\n   END IF;\n\n  ELSIF p_action='prioritize' THEN\n   IF actor.role<>'manager' THEN RAISE EXCEPTION 'Manager required' USING ERRCODE='42501'; END IF;\n   IF p_data->>'priority' NOT IN ('low','normal','high','urgent') THEN RAISE EXCEPTION 'Invalid priority' USING ERRCODE='22023'; END IF;\n   UPDATE public.demo_work_requests SET priority=p_data->>'priority',version=version+1 WHERE id=r.id;\n   INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details)\n   VALUES(r.id,actor.id,'priority_changed',jsonb_build_object('priority',p_data->>'priority'));\n   result:=jsonb_build_object('id',r.id,'priority',p_data->>'priority');\n\n  ELSIF p_action IN ('approve','deny','accept','start') THEN\n   IF r.hub_draft OR r.version IS DISTINCT FROM (p_data->>'version')::int THEN RAISE EXCEPTION 'Refresh required' USING ERRCODE='PT409'; END IF;\n   IF p_action IN ('approve','deny') THEN\n    IF actor.role<>'manager' THEN RAISE EXCEPTION 'Manager required' USING ERRCODE='42501'; END IF;\n    IF NOT actor.hub_approval_enabled THEN RAISE EXCEPTION 'Pilot approval restricted' USING ERRCODE='42501'; END IF;\n    IF r.status NOT IN ('submitted','approved','assigned') THEN RAISE EXCEPTION 'Order already started or closed' USING ERRCODE='PT409'; END IF;\n    IF p_action='approve' THEN\n     IF r.status<>'submitted' OR EXISTS(SELECT FROM public.demo_work_order_events WHERE work_request_id=r.id AND event_type='approve') THEN\n      RAISE EXCEPTION 'Request already approved. Refresh the Hub; use Reassign to change the employee.' USING ERRCODE='PT409';\n     END IF;\n     IF COALESCE(p_data->>'priority','') NOT IN ('low','normal','high','urgent') OR length(COALESCE(p_data->>'notes',''))>4000 THEN RAISE EXCEPTION 'Invalid priority or notes' USING ERRCODE='22023'; END IF;\n     target:=NULLIF(p_data->>'assignee','')::uuid;\n     IF target IS NOT NULL THEN\n       IF NOT EXISTS(SELECT FROM public.demo_employees WHERE id=target AND active AND hub_access_enabled AND NOT hub_access_blocked AND role IN ('employee','shop','manager')) THEN \n         RAISE EXCEPTION 'Active employee assignee required' USING ERRCODE='22023'; \n       END IF;\n     ELSIF NOT v_self_assign_enabled THEN\n       RAISE EXCEPTION 'Active employee assignee required' USING ERRCODE='22023';\n     END IF;\n     IF p_data ? 'due_date' THEN d:=NULLIF(p_data->>'due_date','')::date; IF d<(now()at time zone 'America/Los_Angeles')::date THEN RAISE EXCEPTION 'Due date is in the past' USING ERRCODE='22023';END IF;ELSE d:=r.due_date;END IF;\n     IF p_data ? 'requires_verification' AND jsonb_typeof(p_data->'requires_verification')<>'boolean' THEN RAISE EXCEPTION 'Invalid inspection requirement' USING ERRCODE='22023';END IF;\n     \n     IF target IS NOT NULL THEN\n       UPDATE public.demo_work_requests SET due_date=d,requires_verification=COALESCE((p_data->>'requires_verification')::boolean,requires_verification),status='assigned',assigned_to=target,priority=p_data->>'priority',shop_instructions=left(p_data->>'notes',4000),acknowledged_at=NULL,help_reason=NULL,completion_revision=completion_revision+1,version=version+1 WHERE id=r.id;\n       IF v_self_assign_enabled THEN\n         -- Safely demote existing active lead to assistant before setting target to lead\n         UPDATE public.demo_work_order_assignments\n         SET assignment_role = 'assistant', updated_at = now()\n         WHERE work_request_id = r.id AND status = 'active' AND assignment_role = 'lead' AND employee_id <> target;\n\n         INSERT INTO public.demo_work_order_assignments(work_request_id,employee_id,assignment_role,status,joined_at)\n         VALUES(r.id,target,'lead','active',now())\n         ON CONFLICT (work_request_id, employee_id) WHERE status='active' DO UPDATE SET assignment_role='lead',left_at=NULL;\n       END IF;\n     ELSE\n       -- Opened for shop self-assignment claim\n       UPDATE public.demo_work_requests SET due_date=d,requires_verification=COALESCE((p_data->>'requires_verification')::boolean,requires_verification),status='approved',assigned_to=NULL,priority=p_data->>'priority',shop_instructions=left(p_data->>'notes',4000),acknowledged_at=NULL,help_reason=NULL,completion_revision=completion_revision+1,version=version+1 WHERE id=r.id;\n     END IF;\n    ELSE\n     description:=btrim(p_data->>'reason'); IF description IS NULL OR length(description)<3 OR length(description)>2000 THEN RAISE EXCEPTION 'Denial reason required' USING ERRCODE='22023'; END IF;\n     UPDATE public.demo_work_requests SET status='denied',denial_reason=btrim(p_data->>'reason'),version=version+1 WHERE id=r.id;\n    END IF;\n   ELSE\n    IF r.assigned_to IS DISTINCT FROM actor.id THEN RAISE EXCEPTION 'Assignee required' USING ERRCODE='42501'; END IF;\n    IF (p_action='accept' AND r.status<>'assigned') OR (p_action='start' AND r.status<>'accepted') THEN RAISE EXCEPTION 'Refresh required' USING ERRCODE='PT409'; END IF;\n    UPDATE public.demo_work_requests SET status=CASE WHEN p_action='accept' THEN 'accepted' ELSE 'in_progress' END,acknowledged_at=CASE WHEN p_action='accept' THEN now() ELSE acknowledged_at END,version=version+1 WHERE id=r.id;\n   END IF;\n   INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details) VALUES(r.id,actor.id,p_action,jsonb_build_object('from',r.status,'assignee',target,'reason',p_data->>'reason'));\n   result:=jsonb_build_object('id',r.id);\n\n  ELSIF p_action='part_create' THEN\n   IF (actor.role<>'manager' AND r.assigned_to IS DISTINCT FROM actor.id AND NOT EXISTS (SELECT 1 FROM public.demo_work_order_assignments woa WHERE woa.work_request_id = r.id AND woa.employee_id = actor.id AND woa.status = 'active')) OR r.hub_draft OR r.status NOT IN ('assigned','accepted','in_progress','approved','needs_help') THEN RAISE EXCEPTION 'Active assignment required' USING ERRCODE='42501'; END IF;\n   description:=btrim(p_data->>'description');\n   IF description IS NULL OR length(description)<1 OR length(description)>1000 OR COALESCE((p_data->>'quantity')::int,0) NOT BETWEEN 1 AND 10000 OR length(btrim(COALESCE(p_data->>'reason','')))<3 OR length(p_data->>'reason')>2000 OR length(COALESCE(p_data->>'part_number',''))>200 OR length(COALESCE(p_data->>'supplier',''))>500 THEN RAISE EXCEPTION 'Part details required' USING ERRCODE='22023'; END IF;\n   INSERT INTO public.demo_hub_parts(id,work_request_id,requested_by,description,quantity,part_number,supplier,reason) VALUES(oid,r.id,actor.id,description,(p_data->>'quantity')::int,COALESCE(p_data->>'part_number',''),COALESCE(p_data->>'supplier',''),p_data->>'reason');\n   INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details) VALUES(r.id,actor.id,'parts_requested',jsonb_build_object('part_id',oid));\n   result:=jsonb_build_object('id',oid);\n\n  ELSIF p_action='part_stock' THEN\n   IF actor.role<>'manager' THEN RAISE EXCEPTION 'Manager required' USING ERRCODE='42501'; END IF;\n   SELECT * INTO part FROM public.demo_hub_parts WHERE id=(p_data->>'id')::uuid FOR UPDATE;\n   IF part.version IS DISTINCT FROM (p_data->>'version')::int THEN RAISE EXCEPTION 'Refresh required' USING ERRCODE='PT409'; END IF;\n   IF part.state<>'approved' OR (part.work_request_id IS NOT NULL AND (r.hub_draft OR r.status NOT IN ('assigned','accepted','in_progress','approved','needs_help'))) THEN RAISE EXCEPTION 'Approved active part required' USING ERRCODE='PT409'; END IF;\n   IF length(btrim(COALESCE(p_data->>'location','')))<2 OR length(p_data->>'location')>300 THEN RAISE EXCEPTION 'Stock location required' USING ERRCODE='22023'; END IF;\n   UPDATE public.demo_hub_parts SET procurement_method='stock',stock_location=btrim(p_data->>'location'),pickup_employee_id=NULL,pickup_store=NULL,pickup_notes=NULL,version=version+1,updated_at=now() WHERE id=part.id;\n   IF r.id IS NOT NULL THEN INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details) VALUES(r.id,actor.id,'parts_stock_selected',jsonb_build_object('part_id',part.id,'location',btrim(p_data->>'location'))); END IF;\n   result:=jsonb_build_object('id',part.id);\n\n  ELSIF p_action='part_pickup' THEN\n   IF actor.role<>'manager' THEN RAISE EXCEPTION 'Manager required' USING ERRCODE='42501'; END IF;\n   SELECT * INTO part FROM public.demo_hub_parts WHERE id=(p_data->>'id')::uuid FOR UPDATE;\n   IF part.version IS DISTINCT FROM (p_data->>'version')::int THEN RAISE EXCEPTION 'Refresh required' USING ERRCODE='PT409'; END IF;\n   IF part.state<>'approved' OR (part.work_request_id IS NOT NULL AND (r.hub_draft OR r.status NOT IN ('assigned','accepted','in_progress','approved','needs_help'))) THEN RAISE EXCEPTION 'Approved active part required' USING ERRCODE='PT409'; END IF;\n   target:=NULLIF(p_data->>'assignee','')::uuid;\n   IF target IS NULL OR NOT EXISTS(SELECT FROM public.demo_employees WHERE id=target AND active AND hub_access_enabled AND NOT hub_access_blocked) THEN RAISE EXCEPTION 'Active employee required' USING ERRCODE='22023'; END IF;\n   IF length(btrim(COALESCE(p_data->>'store','')))<2 OR length(p_data->>'store')>300 OR length(COALESCE(p_data->>'notes',''))>2000 THEN RAISE EXCEPTION 'Store required' USING ERRCODE='22023'; END IF;\n   UPDATE public.demo_hub_parts SET procurement_method='local',stock_location=NULL,pickup_employee_id=target,pickup_store=btrim(p_data->>'store'),pickup_notes=COALESCE(p_data->>'notes',''),version=version+1,updated_at=now() WHERE id=part.id;\n   IF r.id IS NOT NULL THEN\n   INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details) VALUES(r.id,actor.id,'parts_pickup_assigned',jsonb_build_object('part_id',part.id,'employee_id',target,'store',btrim(p_data->>'store')));\n   END IF;\n   result:=jsonb_build_object('id',part.id);\n\n  ELSIF p_action='part_update' THEN\n   SELECT * INTO part FROM public.demo_hub_parts WHERE id=(p_data->>'id')::uuid FOR UPDATE;\n   IF part.version IS DISTINCT FROM (p_data->>'version')::int THEN RAISE EXCEPTION 'Refresh required' USING ERRCODE='PT409'; END IF;\n   next_state:=p_data->>'state';\n   IF actor.role<>'manager' AND ((part.work_request_id IS NULL AND actor.role<>'shop') OR ((CASE WHEN part.work_request_id IS NULL THEN part.requested_by ELSE r.assigned_to END) IS DISTINCT FROM actor.id AND NOT EXISTS (SELECT 1 FROM public.demo_work_order_assignments woa WHERE woa.work_request_id = r.id AND woa.employee_id = actor.id AND woa.status = 'active')) OR next_state NOT IN ('received','installed')) THEN RAISE EXCEPTION 'Not permitted' USING ERRCODE='42501'; END IF;\n   IF NOT ((part.state='pending' AND next_state IN ('approved','denied')) OR (part.state='approved' AND next_state='ordered' AND part.pickup_employee_id IS NULL AND part.procurement_method IS DISTINCT FROM 'stock') OR (part.state='approved' AND next_state='received' AND (part.pickup_employee_id IS NOT NULL OR part.procurement_method='stock')) OR (part.state='ordered' AND next_state='received') OR (part.state='received' AND next_state='installed' AND part.work_request_id IS NOT NULL)) THEN RAISE EXCEPTION 'Invalid transition' USING ERRCODE='PT409'; END IF;\n   IF next_state='ordered' AND (length(btrim(COALESCE(p_data->>'reason','')))<3 OR length(btrim(COALESCE(p_data->>'supplier','')))<2 OR length(p_data->>'supplier')>500) THEN RAISE EXCEPTION 'Local unavailability reason and supplier required' USING ERRCODE='22023'; END IF;\n   IF next_state='denied' AND length(btrim(COALESCE(p_data->>'reason','')))<3 THEN RAISE EXCEPTION 'Denial reason required' USING ERRCODE='22023'; END IF;\n   IF length(COALESCE(p_data->>'reason',''))>2000 THEN RAISE EXCEPTION 'Reason too long' USING ERRCODE='22023'; END IF;\n   UPDATE public.demo_hub_parts SET state=next_state,procurement_method=CASE WHEN next_state='ordered' THEN 'supplier' ELSE procurement_method END,local_unavailable_reason=CASE WHEN next_state='ordered' THEN btrim(p_data->>'reason') ELSE local_unavailable_reason END,supplier=CASE WHEN next_state='ordered' THEN btrim(p_data->>'supplier') ELSE supplier END,decision_reason=CASE WHEN next_state='denied' THEN p_data->>'reason' ELSE decision_reason END,version=version+1,updated_at=now() WHERE id=part.id;\n   IF r.id IS NOT NULL THEN\n   INSERT INTO public.demo_work_order_events(work_request_id,actor_employee_id,event_type,details) VALUES(r.id,actor.id,'parts_'||next_state,jsonb_build_object('part_id',part.id,'reason',p_data->>'reason'));\n   END IF;\n   result:=jsonb_build_object('id',COALESCE(r.id,part.id));\n  END IF;\n END IF;\n INSERT INTO public.demo_hub_operations(actor_id,operation_id,action,input,result) VALUES(actor.id,oid,p_action,p_data,result);\n RETURN result;\nEND $function$;","CREATE OR REPLACE FUNCTION public.demo_hub_report(p_token uuid, p_asset uuid DEFAULT NULL::uuid, p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_status text DEFAULT ''::text, p_offset integer DEFAULT 0)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''\nAS $function$\nDECLARE actor public.demo_employees%ROWTYPE; result jsonb;\nBEGIN\n SELECT * INTO actor FROM public.demo_hub_actor(p_token);\n IF NOT FOUND OR actor.id IS NULL THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='28000'; END IF;\n IF actor.role <> 'manager' THEN RAISE EXCEPTION 'Manager required' USING ERRCODE='42501'; END IF;\n IF p_offset IS NULL OR p_offset < 0 OR p_offset > 1000000 OR p_status IS NULL OR p_status NOT IN ('','submitted','approved','assigned','accepted','in_progress','completed','closed','denied','needs_help','awaiting_verification') OR p_start > p_end THEN RAISE EXCEPTION 'Invalid filters' USING ERRCODE='22023'; END IF;\n WITH filtered AS MATERIALIZED (\n SELECT r.* FROM public.demo_work_requests r WHERE NOT r.hub_draft AND NOT COALESCE(r.is_test, false) AND (p_asset IS NULL OR r.asset_id=p_asset)\n AND (p_start IS NULL OR r.submission_date >= p_start::timestamp AT TIME ZONE 'UTC')\n AND (p_end IS NULL OR r.submission_date < (p_end+1)::timestamp AT TIME ZONE 'UTC')\n AND (p_status='' OR r.status=p_status)\n ), page AS (SELECT * FROM filtered ORDER BY submission_date DESC,id DESC LIMIT 20 OFFSET p_offset)\n SELECT jsonb_build_object('total',(SELECT count(*) FROM filtered),'offset',p_offset,'page_size',20,'generated_at',now(),\n 'records',COALESCE((SELECT jsonb_agg(jsonb_build_object(\n 'id',r.id,'number',r.work_order_number,'asset',a.asset_name,'asset_number',a.asset_number,\n 'due_date',r.due_date,'requires_verification',r.requires_verification,'verified_at',r.verified_at,'verified_by',(SELECT full_name FROM public.demo_employees WHERE id=r.verified_by),'verification_notes',r.verification_notes,'work_kind',r.work_kind,'work_date',r.work_date,'description',r.description,'status',r.status,'priority',r.priority,'submitted_at',r.submission_date,'completed_at',r.completed_at,\n 'requester',requester.full_name,'assigned_to',assignee.full_name,'manager_notes',r.manager_notes,'instructions',r.shop_instructions,\n 'verification_signature',r.verification_signature,'verification_signer_name',r.verification_signer_name,'verification_signed_at',r.verification_signed_at,\n  'completions',COALESCE((SELECT jsonb_agg(jsonb_build_object('current',c.revision=r.completion_revision,'notes',c.completion_notes,'date',c.completion_date,'completed_by',e.full_name,'signature',c.signature,'signer_name',c.signer_name,'signed_at',c.signed_at) ORDER BY c.completion_date,c.id) FROM public.demo_work_completions c LEFT JOIN public.demo_employees e ON e.id=c.completed_by WHERE c.work_request_id=r.id),'[]'::jsonb),\n  'inspections',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',si.id,'revision',si.completion_revision,'passed',si.passed,'notes',si.notes,'signature',si.signature_png,'signer_name',si.signer_name,'signed_at',si.signed_at) ORDER BY si.signed_at,si.id) FROM public.demo_work_order_inspection_signatures si WHERE si.work_request_id=r.id),'[]'::jsonb),\n 'crew_contributions',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',cs.id,'employee',ce.full_name,'revision',cs.completion_revision,'notes',cs.work_performed,'signature',cs.signature_png,'signer_name',cs.signer_name,'signed_at',cs.signed_at,'checksum',cs.signature_md5) ORDER BY cs.signed_at,cs.id) FROM public.demo_work_order_contribution_signatures cs JOIN public.demo_employees ce ON ce.id=cs.employee_id WHERE cs.work_request_id=r.id),'[]'::jsonb),\n 'photos',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',p.id,'photo_type',p.photo_type,'file_name',p.file_name,'created_at',p.created_at) ORDER BY p.created_at,p.id) FROM public.demo_work_order_photos p WHERE p.work_request_id=r.id AND p.upload_state='ready' AND p.superseded_at IS NULL),'[]'::jsonb),\n 'events',COALESCE((SELECT jsonb_agg(jsonb_build_object('event_type',v.event_type,'created_at',v.created_at) ORDER BY v.created_at,v.id) FROM public.demo_work_order_events v WHERE v.work_request_id=r.id),'[]'::jsonb)\n ) ORDER BY r.submission_date DESC,r.id DESC) FROM page r LEFT JOIN public.demo_assets a ON a.id=r.asset_id LEFT JOIN public.demo_employees requester ON requester.id=r.requester_id LEFT JOIN public.demo_employees assignee ON assignee.id=r.assigned_to),'[]'::jsonb)) INTO result;\n RETURN result;\nEND $function$;","CREATE OR REPLACE FUNCTION public.demo_hub_snapshot(p_token uuid)\n RETURNS jsonb\n LANGUAGE sql\n STABLE\n SET search_path TO ''\nAS $function$ SELECT public.demo_hub_snapshot_page(p_token,NULL); $function$;","CREATE OR REPLACE FUNCTION public.demo_hub_assistant_allow(p_token uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nDECLARE actor public.demo_employees%ROWTYPE;\nBEGIN\nSELECT * INTO actor FROM public.demo_hub_actor(p_token);\nIF NOT FOUND THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='28000';END IF;\nPERFORM pg_advisory_xact_lock(72499113);\nIF (SELECT count(*) FROM public.demo_hub_assistant_usage WHERE created_at>=date_trunc('day',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC')>=100 OR (SELECT count(*) FROM public.demo_hub_assistant_usage WHERE created_at>now()-interval '1 minute')>=5 OR (SELECT count(*) FROM public.demo_hub_assistant_usage WHERE employee_id=actor.id AND created_at>now()-interval '1 day')>=50 THEN RAISE EXCEPTION 'Assistant limit reached' USING ERRCODE='54000';END IF;\nINSERT INTO public.demo_hub_assistant_usage(employee_id) VALUES(actor.id);\nRETURN jsonb_build_object('role',actor.role);\nEND $function$;","CREATE OR REPLACE FUNCTION public.demo_hub_snapshot_page(p_token uuid, p_cursor jsonb DEFAULT NULL::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''\nAS $function$\nDECLARE\n  actor public.demo_employees%ROWTYPE;\n  result jsonb;\n  v_self_assign_enabled boolean;\n  v_include_test boolean;\nBEGIN\n  SELECT * INTO actor FROM public.demo_hub_actor(p_token);\n  IF NOT FOUND OR actor.id IS NULL THEN\n    RAISE EXCEPTION 'Access denied' USING ERRCODE = '28000';\n  END IF;\n  IF p_cursor IS NOT NULL AND jsonb_typeof(p_cursor) = 'object' AND (p_cursor ? 'created_at' OR p_cursor ? 'id') THEN\n    IF p_cursor->>'created_at' IS NULL OR p_cursor->>'id' IS NULL THEN \n      RAISE EXCEPTION 'Invalid cursor' USING ERRCODE='22023'; \n    END IF;\n  ELSIF p_cursor IS NOT NULL AND jsonb_typeof(p_cursor) <> 'object' THEN\n    RAISE EXCEPTION 'Invalid cursor' USING ERRCODE='22023';\n  END IF;\n\n  v_include_test := COALESCE((p_cursor->>'include_test')::boolean, (p_cursor->>'test_mode')::boolean, false);\n\n  WITH flags AS (\n    SELECT COALESCE((SELECT enabled FROM public.demo_hub_feature_flags WHERE feature = 'shop_self_assignment'), false) AS enabled,\n      COALESCE((SELECT test_enabled FROM public.demo_hub_feature_flags WHERE feature = 'shop_self_assignment'), false) AS test_enabled\n  ),\n  permitted AS MATERIALIZED (\n    SELECT r.* FROM public.demo_work_requests r\n    CROSS JOIN flags f\n    WHERE NOT r.hub_draft \n      AND (NOT COALESCE(r.is_test, false) OR (f.test_enabled AND v_include_test AND actor.role IN ('manager', 'shop')))\n      AND (\n        actor.role = 'manager' \n        OR r.requester_id = actor.id\n        OR r.assigned_to = actor.id\n        OR (actor.role = 'shop' AND (\n          (CASE WHEN r.is_test THEN (f.enabled OR f.test_enabled) ELSE f.enabled END) AND (\n            -- Shop technicians can see unassigned approved orders AND eligible claimed active orders to join!\n            r.status IN ('approved', 'assigned', 'accepted', 'in_progress')\n            OR EXISTS (\n              SELECT 1 FROM public.demo_work_order_assignments woa \n              WHERE woa.work_request_id = r.id AND woa.employee_id = actor.id\n            )\n          )\n        ))\n      )\n    AND (p_cursor IS NULL OR (p_cursor->>'created_at') IS NULL OR (r.created_at,r.id)<((p_cursor->>'created_at')::timestamptz,(p_cursor->>'id')::uuid))\n    ORDER BY r.created_at DESC, r.id DESC LIMIT 201\n  ), visible AS MATERIALIZED (\n    SELECT * FROM permitted ORDER BY created_at DESC, id DESC LIMIT 200\n  )\n  SELECT jsonb_build_object(\n    'employee', jsonb_build_object('id',actor.id,'full_name',actor.full_name,\n      'role',actor.role,'can_approve',actor.role='manager' AND actor.hub_approval_enabled,'department',actor.department,'slack_user_id',actor.slack_user_id),\n    'employee_links',CASE WHEN actor.role='manager' THEN COALESCE((SELECT jsonb_agg(jsonb_build_object('id',e.id,'name',e.full_name,'role',e.role,'department',COALESCE(e.department,''),'token',e.hub_token) ORDER BY e.full_name,e.id) FROM public.demo_employees e WHERE e.active AND e.hub_access_enabled AND NOT e.hub_access_blocked AND e.hub_token IS NOT NULL),'[]'::jsonb) ELSE '[]'::jsonb END,\n    'read_only',true,\n    'has_more',(SELECT count(*) > 200 FROM permitted),\n    'next_cursor',CASE WHEN (SELECT count(*)>200 FROM permitted) THEN (SELECT jsonb_build_object('created_at',created_at,'id',id) FROM visible ORDER BY created_at,id LIMIT 1) ELSE NULL END,\n    'assets',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',a.id,\n      'asset_name',a.asset_name,'asset_number',a.asset_number,'asset_type',a.asset_type,\n      'active',a.active) ORDER BY a.asset_name,a.id)\n      FROM public.demo_assets a WHERE actor.role = 'manager' OR (actor.role IN ('employee','shop') AND a.active) OR a.id IN (SELECT asset_id FROM visible)),'[]'::jsonb),\n    'work_requests',COALESCE((SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object(\n      'id',v.id,'due_date',v.due_date,'requires_verification',v.requires_verification,'verified_at',v.verified_at,'verified_by_name',(SELECT full_name FROM public.demo_employees WHERE id=v.verified_by),'verification_notes',v.verification_notes,'version',v.version,'completion_revision',v.completion_revision,'help_reason',v.help_reason,'work_kind',v.work_kind,'work_date',v.work_date,'work_order_number',v.work_order_number,'requester_id',v.requester_id,\n      'requester_name',requester.full_name,'assigned_to',v.assigned_to,\n      'assignee_name',assignee.full_name,'asset_id',v.asset_id,'description',v.description,'problem_photo_unavailable_reason',v.problem_photo_unavailable_reason,\n      'priority',v.priority,'status',v.status,'submission_date',v.submission_date,\n      'completed_at',v.completed_at,'denial_reason',v.denial_reason,\n      'instructions',CASE WHEN actor.role='manager' OR v.assigned_to=actor.id THEN v.shop_instructions ELSE NULL END,\n      'manager_notes',CASE WHEN actor.role='manager' THEN v.manager_notes ELSE NULL END,\n      'is_safety_critical',COALESCE(v.is_safety_critical,false),\n      'safety_hold',COALESCE(v.safety_hold,false),\n      'is_test',COALESCE(v.is_test,false),\n      'verification_signature',CASE WHEN actor.role='manager' THEN v.verification_signature ELSE NULL END,\n      'verification_signer_name',v.verification_signer_name,\n      'verification_signed_at',v.verification_signed_at,\n      'assignments',COALESCE((\n        SELECT jsonb_agg(jsonb_build_object(\n          'id', a.id,\n          'work_request_id', a.work_request_id,\n          'employee_id', a.employee_id,\n          'employee_name', ae.full_name,\n          'role', a.assignment_role,\n          'status', a.status,\n          'joined_at', a.joined_at,\n          'left_at', a.left_at,\n          'work_performed', a.work_performed,\n          'contribution_signed_at',a.contribution_signed_at,\n          'contribution_revision',a.contribution_revision\n        ) ORDER BY a.joined_at, a.id)\n        FROM public.demo_work_order_assignments a\n        JOIN public.demo_employees ae ON ae.id = a.employee_id\n        WHERE a.work_request_id = v.id\n      ), '[]'::jsonb)\n    )) ORDER BY v.created_at DESC,v.id DESC) FROM visible v\n      LEFT JOIN public.demo_employees requester ON requester.id=v.requester_id\n      LEFT JOIN public.demo_employees assignee ON assignee.id=v.assigned_to),'[]'::jsonb),\n    'parts_requests',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',p.id,'work_request_id',p.work_request_id,'requested_by',e.full_name,'description',p.description,'quantity',p.quantity,'state',p.state,'created_at',p.created_at,'reason',p.reason,'version',p.version,'part_number',p.part_number,'supplier',p.supplier)) FROM public.demo_hub_parts p LEFT JOIN visible v ON v.id=p.work_request_id LEFT JOIN public.demo_employees e ON e.id=p.requested_by WHERE (v.id IS NOT NULL OR p.work_request_id IS NULL) AND (actor.role='manager' OR (v.assigned_to=actor.id OR EXISTS (SELECT 1 FROM public.demo_work_order_assignments woa WHERE woa.work_request_id = v.id AND woa.employee_id = actor.id AND woa.status = 'active') OR (actor.role='shop' AND p.work_request_id IS NULL AND p.requested_by=actor.id)))),'[]'::jsonb),\n    'work_completions',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',c.id,\n      'work_request_id',c.work_request_id,'completion_notes',c.completion_notes,\n      'completion_date',c.completion_date,'completed_by',c.completed_by,'revision',c.revision,'current',c.revision=v.completion_revision,\n      'signature',CASE WHEN actor.role='manager' OR c.completed_by=actor.id THEN c.signature ELSE NULL END,\n      'signer_name',c.signer_name,'signed_at',c.signed_at) ORDER BY c.completion_date,c.id)\n      FROM public.demo_work_completions c JOIN visible v ON v.id=c.work_request_id),'[]'::jsonb),\n    'work_order_photos',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',p.id,\n      'work_request_id',p.work_request_id,'photo_type',p.photo_type,\n      'file_name',p.file_name,'created_at',p.created_at) ORDER BY p.created_at,p.id)\n      FROM public.demo_work_order_photos p JOIN visible v ON v.id=p.work_request_id WHERE p.upload_state='ready' AND p.superseded_at IS NULL),'[]'::jsonb),\n    'work_order_events',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',e.id,\n      'work_request_id',e.work_request_id,'event_type',e.event_type,'created_at',e.created_at,'reason',CASE WHEN e.event_type IN ('need_help','reassign','reopen','correct','photo_replaced','completion_corrected','photo_unavailable','schedule','work_verified','job_claimed','worker_joined','worker_left','priority_changed','safety_hold_placed','safety_hold_released','safety_escalated','inspection_failed') THEN e.details->>'reason' END)\n      ORDER BY e.created_at,e.id) FROM public.demo_work_order_events e\n      JOIN visible v ON v.id=e.work_request_id),'[]'::jsonb)\n  ) INTO result;\n  RETURN result;\nEND;\n$function$;\n","CREATE OR REPLACE FUNCTION public.demo_hub_actor(p_token uuid)\n RETURNS public.demo_employees\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare actor public.demo_employees%rowtype; session demo_hub_auth.sessions%rowtype;\nbegin\n select * into actor from public.demo_employees where hub_token=p_token and active and hub_access_enabled and not hub_access_blocked;\n if found then\n  if actor.role='manager' and (select require_manager_verification from demo_hub_auth.settings where id)then raise exception 'Manager verification required' using errcode='PMA01';end if;\n  return actor;\n end if;\n select * into session from demo_hub_auth.sessions where id=p_token;\n if not found then raise exception 'Access denied' using errcode='28000';end if;\n select * into actor from public.demo_employees where id=session.employee_id and active and hub_access_enabled and not hub_access_blocked and hub_access_version=session.access_version and role='manager';\n if not found then raise exception 'Access denied' using errcode='28000';end if;\n if session.revoked_at is not null then raise exception 'Access denied' using errcode='28000';end if;\n if session.expires_at<=now() or session.last_active_at<=now()-interval '30 minutes' then raise exception 'Manager verification required' using errcode='PMA01';end if;\n return actor;\nend $function$;","CREATE OR REPLACE FUNCTION public.demo_hub_authentication(p_token uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare actor public.demo_employees%rowtype; session demo_hub_auth.sessions%rowtype; challenge demo_hub_auth.challenges%rowtype; cid uuid; secret text; code text; session_id uuid; bot text;\nbegin\n if p_action in('touch','signout')then\n  if p_action='signout'then update demo_hub_auth.sessions set revoked_at=now()where id=p_token and revoked_at is null;return jsonb_build_object('ok',true);end if;\n  actor:=public.demo_hub_actor(p_token);\n  update demo_hub_auth.sessions set last_active_at=now()where id=p_token and revoked_at is null;\n  return jsonb_build_object('ok',true);\n end if;\n select * into actor from public.demo_employees where hub_token=p_token and active and hub_access_enabled and not hub_access_blocked and role='manager';\n if not found then\n  select * into session from demo_hub_auth.sessions where id=p_token and revoked_at is null;\n  if found then select * into actor from public.demo_employees where id=session.employee_id and hub_access_version=session.access_version and role='manager' and active and hub_access_enabled and not hub_access_blocked;end if;\n end if;\n if actor.id is null or actor.role<>'manager' or actor.slack_user_id is null then raise exception 'Access denied' using errcode='28000';end if;\n perform pg_advisory_xact_lock(hashtextextended(actor.id::text,409));\n select decrypted_secret into strict secret from vault.decrypted_secrets where name='demo_pms_hub_signin_key';\n if p_action='request'then\n  cid:=(p_data->>'operation_id')::uuid;\n  if cid is null then raise exception 'Operation required' using errcode='22023';end if;\n  select * into challenge from demo_hub_auth.challenges where id=cid;\n  if found then\n   if challenge.employee_id<>actor.id or challenge.access_version<>actor.hub_access_version then raise exception 'Access denied' using errcode='28000';end if;\n   return jsonb_build_object('id',challenge.id,'expires_at',challenge.expires_at,'state',challenge.delivery_state,'dispatch',false);\n  end if;\n  if exists(select 1 from demo_hub_auth.challenges where employee_id=actor.id and created_at>now()-interval '60 seconds')or(select count(*)from demo_hub_auth.challenges where employee_id=actor.id and created_at>now()-interval '1 hour')>=5 then raise exception 'Wait before requesting another code' using errcode='PMA02';end if;\n  select decrypted_secret into strict bot from vault.decrypted_secrets where name='demo_pms_hub_slack_bot_token';\n  code:=lpad(((('x'||encode(extensions.gen_random_bytes(4),'hex'))::bit(32)::bigint)%100000000)::text,8,'0');\n  update demo_hub_auth.challenges set consumed_at=now()where employee_id=actor.id and consumed_at is null;\n  insert into demo_hub_auth.challenges(id,employee_id,access_version,code_hash,code_cipher)values(cid,actor.id,actor.hub_access_version,encode(extensions.hmac(cid::text||':'||code,secret,'sha256'),'hex'),extensions.pgp_sym_encrypt(code,secret))returning * into challenge;\n  -- Private dispatch fields are consumed by the Edge handler and never returned to the browser.\n  return jsonb_build_object('id',cid,'expires_at',challenge.expires_at,'state','sending','dispatch',true,'slack_user_id',actor.slack_user_id,'code',code,'bot_token',bot);\n elsif p_action='status'then\n  select * into challenge from demo_hub_auth.challenges where id=(p_data->>'id')::uuid and employee_id=actor.id;\n  if not found then raise exception 'Challenge unavailable' using errcode='P0002';end if;\n  return jsonb_build_object('id',challenge.id,'state',challenge.delivery_state,'expires_at',challenge.expires_at);\n elsif p_action='verify'then\n  select * into challenge from demo_hub_auth.challenges where id=(p_data->>'id')::uuid and employee_id=actor.id for update;\n  if not found or challenge.access_version<>actor.hub_access_version or challenge.consumed_at is not null or challenge.expires_at<=now() or challenge.attempts>=5 then return jsonb_build_object('ok',false,'error','Code expired or unavailable. Request a new code.');end if;\n  update demo_hub_auth.challenges set attempts=attempts+1 where id=challenge.id;\n  code:=coalesce(p_data->>'code','');\n  if code!~'^\\d{8}$' or encode(extensions.hmac(challenge.id::text||':'||code,secret,'sha256'),'hex')<>challenge.code_hash then return jsonb_build_object('ok',false,'error','Code not accepted. Check Slack and try again.');end if;\n  update demo_hub_auth.challenges set consumed_at=now()where id=challenge.id;\n  insert into demo_hub_auth.sessions(employee_id,access_version)values(actor.id,actor.hub_access_version)returning id into session_id;\n  return jsonb_build_object('ok',true,'session',session_id,'expires_at',now()+interval '8 hours');\n end if;\n raise exception 'Invalid action' using errcode='22023';\nend $function$;","CREATE OR REPLACE FUNCTION public.demo_hub_health(p_token uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare actor public.demo_employees%rowtype;\nbegin\n actor:=public.demo_hub_actor(p_token);\n if actor.role<>'manager'then raise exception 'Manager required'using errcode='42501';end if;\n  RETURN jsonb_build_object('last_sync',null,'last_verified_backup',null,'notification_failures',0,'notification_backlog',0,'notification_recipients',(select count(*) from public.demo_employees where active and hub_access_enabled and not hub_access_blocked),'notifications_enabled',false);\nend $function$;","CREATE OR REPLACE FUNCTION public.demo_hub_validate_troubleshooting_guide(p_guide jsonb)\n RETURNS boolean\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''\nAS $function$\ndeclare q jsonb; c jsonb; ids text[] := array[]::text[]; qid text; start_id text; nxt text; outc text;\nbegin\n  if p_guide is null or jsonb_typeof(p_guide)<>'object' then return false; end if;\n  if jsonb_typeof(p_guide->'questions')<>'array' or jsonb_array_length(p_guide->'questions') not between 1 and 60 then return false; end if;\n  if jsonb_typeof(p_guide->'title')<>'object'\n     or length(btrim(coalesce(p_guide#>>'{title,en}',''))) not between 1 and 150\n     or length(btrim(coalesce(p_guide#>>'{title,es}',''))) not between 1 and 150 then return false; end if;\n  if jsonb_typeof(p_guide->'outcomes')<>'object' then return false; end if;\n  if length(btrim(coalesce(p_guide#>>'{outcomes,safety_work_order,en}',''))) < 1\n     or length(btrim(coalesce(p_guide#>>'{outcomes,safety_work_order,es}',''))) < 1 then return false; end if;\n  if length(btrim(coalesce(p_guide#>>'{outcomes,work_order,en}',''))) < 1\n     or length(btrim(coalesce(p_guide#>>'{outcomes,work_order,es}',''))) < 1 then return false; end if;\n  start_id:=p_guide->>'start';\n  if start_id is null or start_id !~ '^[A-Za-z0-9_-]{1,50}$' then return false; end if;\n  for q in select value from jsonb_array_elements(p_guide->'questions') loop\n    qid:=q->>'id';\n    if qid is null or qid !~ '^[A-Za-z0-9_-]{1,50}$' or qid=any(ids) then return false; end if;\n    ids:=array_append(ids,qid);\n    if q->>'type' not in ('text','choice') then return false; end if;\n    if length(btrim(coalesce(q#>>'{prompt,en}',''))) not between 1 and 700\n       or length(btrim(coalesce(q#>>'{prompt,es}',''))) not between 1 and 700 then return false; end if;\n    if q->>'type'='choice' then\n      if jsonb_typeof(q->'choices')<>'array'\n         or jsonb_array_length(q->'choices') not between 2 and 12 then return false; end if;\n      for c in select value from jsonb_array_elements(q->'choices') loop\n        if length(btrim(coalesce(c->>'value',''))) not between 1 and 80\n           or length(btrim(coalesce(c->>'en',''))) not between 1 and 300\n           or length(btrim(coalesce(c->>'es',''))) not between 1 and 300 then return false; end if;\n      end loop;\n    end if;\n  end loop;\n  if not (start_id=any(ids)) then return false; end if;\n  for q in select value from jsonb_array_elements(p_guide->'questions') loop\n    if q->>'type'='choice' then\n      for c in select value from jsonb_array_elements(q->'choices') loop\n        nxt:=c->>'next'; outc:=c->>'outcome';\n        if nullif(nxt,'') is not null and not (nxt=any(ids)) then return false; end if;\n        if nullif(nxt,'') is null and (outc is null or not (p_guide->'outcomes' ? outc)) then return false; end if;\n      end loop;\n    else\n      nxt:=q->>'next'; outc:=q->>'outcome';\n      if nullif(nxt,'') is not null and not (nxt=any(ids)) then return false; end if;\n      if nullif(nxt,'') is null and (outc is null or not (p_guide->'outcomes' ? outc)) then return false; end if;\n    end if;\n  end loop;\n  return true;\nexception when others then return false;\nend $function$;","CREATE OR REPLACE FUNCTION public.demo_hub_troubleshooting_workflow(p_token uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\ndeclare\n  actor public.demo_employees%rowtype;\n  g public.demo_hub_troubleshooting_guides%rowtype;\n  can_edit boolean;\n  oid uuid;\n  op public.demo_hub_operations%rowtype;\n  payload jsonb;\n  k text;\n  asset text;\n  v integer;\n  result jsonb;\nbegin\n  select * into actor from public.demo_hub_actor(p_token);\n  if not found then raise exception 'Access denied' using errcode='28000'; end if;\n  if p_data is null or jsonb_typeof(p_data)<>'object' then raise exception 'Invalid data' using errcode='22023'; end if;\n  select exists(select 1 from public.demo_hub_troubleshooting_editors e where e.employee_id=actor.id) into can_edit;\n\n  if p_action='troubleshooting_active' then\n    asset:=lower(btrim(coalesce(p_data->>'asset','')));\n    if length(asset)<1 or length(asset)>200 then raise exception 'Asset required' using errcode='22023'; end if;\n    select * into g from public.demo_hub_troubleshooting_guides t\n     where t.enabled and t.published is not null\n       and exists(select 1 from unnest(t.asset_match) m where strpos(asset,lower(m))>0)\n     order by t.guide_key limit 1;\n    if not found then return jsonb_build_object('guide',null); end if;\n    return jsonb_build_object(\n      'guide',\n      g.published || jsonb_build_object(\n        'key',g.guide_key,'enabled',true,'approved',true,\n        'version',g.guide_key||'-published-'||g.published_version::text\n      )\n    );\n  elsif p_action='troubleshooting_editor_get' then\n    if actor.role<>'manager' then raise exception 'Manager required' using errcode='42501'; end if;\n    k:=lower(btrim(coalesce(p_data->>'key','gravitron')));\n    select * into g from public.demo_hub_troubleshooting_guides where guide_key=k;\n    if not found then raise exception 'Not found' using errcode='P0002'; end if;\n    return jsonb_build_object(\n      'key',g.guide_key,'title',g.title,\n      'guide',g.draft || jsonb_build_object(\n        'key',g.guide_key,'enabled',false,'approved',false,\n        'version',g.guide_key||'-draft-'||g.draft_version::text\n      ),\n      'draft_version',g.draft_version,'published_version',g.published_version,\n      'enabled',g.enabled,'can_edit',can_edit,\n      'updated_at',g.updated_at,\n      'updated_by',(select full_name from public.demo_employees where id=g.updated_by),\n      'published_at',g.published_at,\n      'published_by',(select full_name from public.demo_employees where id=g.published_by)\n    );\n  end if;\n\n  if p_action not in ('troubleshooting_save','troubleshooting_publish','troubleshooting_disable')\n    then raise exception 'Invalid action' using errcode='22023'; end if;\n  if actor.role<>'manager' or not can_edit\n    then raise exception 'Editor permission required' using errcode='42501'; end if;\n\n  oid:=(p_data->>'operation_id')::uuid;\n  if oid is null then raise exception 'Operation required' using errcode='22023'; end if;\n  perform pg_advisory_xact_lock(hashtextextended(actor.id::text||oid::text,0));\n  select * into op from public.demo_hub_operations where actor_id=actor.id and operation_id=oid;\n  if found then\n    if op.action<>p_action or op.input<>p_data\n      then raise exception 'Retry changed' using errcode='23505'; end if;\n    return op.result;\n  end if;\n\n  k:=lower(btrim(coalesce(p_data->>'key','')));\n  v:=(p_data->>'version')::integer;\n  if k !~ '^[a-z0-9_-]{1,50}$' or v is null or v<1\n    then raise exception 'Invalid version' using errcode='22023'; end if;\n  select * into g from public.demo_hub_troubleshooting_guides where guide_key=k for update;\n  if not found then raise exception 'Not found' using errcode='P0002'; end if;\n  if g.draft_version<>v then raise exception 'Refresh required' using errcode='40001'; end if;\n\n  if p_action='troubleshooting_save' then\n    begin\n      payload:=(p_data->>'guide')::jsonb;\n    exception when others then\n      raise exception 'Invalid guide' using errcode='22023';\n    end;\n    payload:=payload - 'enabled' - 'approved' - 'version' - 'key';\n    if not public.demo_hub_validate_troubleshooting_guide(payload)\n      then raise exception 'Invalid guide' using errcode='22023'; end if;\n    update public.demo_hub_troubleshooting_guides\n       set draft=payload,draft_version=draft_version+1,title=payload->'title',\n           updated_by=actor.id,updated_at=now()\n     where guide_key=k returning * into g;\n    insert into public.demo_hub_troubleshooting_events(guide_key,actor_employee_id,action,version)\n    values(k,actor.id,'save',g.draft_version);\n  elsif p_action='troubleshooting_publish' then\n    if not public.demo_hub_validate_troubleshooting_guide(g.draft)\n      then raise exception 'Invalid guide' using errcode='22023'; end if;\n    update public.demo_hub_troubleshooting_guides\n       set published=draft,published_version=draft_version,enabled=true,\n           published_by=actor.id,published_at=now(),updated_by=actor.id,updated_at=now()\n     where guide_key=k returning * into g;\n    insert into public.demo_hub_troubleshooting_events(guide_key,actor_employee_id,action,version)\n    values(k,actor.id,'publish',g.published_version);\n  else\n    update public.demo_hub_troubleshooting_guides\n       set enabled=false,updated_by=actor.id,updated_at=now()\n     where guide_key=k returning * into g;\n    insert into public.demo_hub_troubleshooting_events(guide_key,actor_employee_id,action,version)\n    values(k,actor.id,'disable',g.draft_version);\n  end if;\n\n  result:=jsonb_build_object(\n    'key',k,'draft_version',g.draft_version,\n    'published_version',g.published_version,'enabled',g.enabled\n  );\n  insert into public.demo_hub_operations(actor_id,operation_id,action,input,result)\n  values(actor.id,oid,p_action,p_data,result);\n  return result;\nend $function$;","CREATE OR REPLACE FUNCTION public.demo_hub_record_activity(p_token uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nDECLARE actor public.demo_employees%ROWTYPE;\nBEGIN\n SELECT * INTO actor FROM public.demo_hub_actor(p_token);\n UPDATE public.demo_employees\n SET hub_first_opened_at=COALESCE(hub_first_opened_at,clock_timestamp()),\n     hub_last_active_at=clock_timestamp()\n WHERE id=actor.id AND active AND hub_access_enabled AND NOT hub_access_blocked\n AND (hub_last_active_at IS NULL OR hub_last_active_at < clock_timestamp()-interval '1 minute');\n RETURN jsonb_build_object('ok',true);\nEND $function$;","CREATE OR REPLACE FUNCTION public.demo_hub_valid_png_signature(p_signature text)\n RETURNS boolean\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''\nAS $function$\nDECLARE\n  v_encoded text;\n  v_png bytea;\n  v_width bigint;\n  v_height bigint;\nBEGIN\n  IF p_signature IS NULL OR length(p_signature) NOT BETWEEN 300 AND 65000\n     OR left(p_signature, 22) <> 'data:image/png;base64,' THEN\n    RETURN false;\n  END IF;\n  v_encoded := substr(p_signature,23);\n  IF length(v_encoded) % 4 <> 0 OR v_encoded !~ '^[A-Za-z0-9+/]+={0,2}$' THEN\n    RETURN false;\n  END IF;\n  v_png := decode(v_encoded, 'base64');\n  IF octet_length(v_png) NOT BETWEEN 200 AND 48000\n     OR substring(v_png from 1 for 8) <> decode('89504e470d0a1a0a','hex')\n     OR substring(v_png from 13 for 4) <> decode('49484452','hex') THEN\n    RETURN false;\n  END IF;\n  v_width := get_byte(v_png,16)*16777216::bigint+get_byte(v_png,17)*65536+get_byte(v_png,18)*256+get_byte(v_png,19);\n  v_height := get_byte(v_png,20)*16777216::bigint+get_byte(v_png,21)*65536+get_byte(v_png,22)*256+get_byte(v_png,23);\n  RETURN v_width BETWEEN 100 AND 2400 AND v_height BETWEEN 40 AND 1200;\nEXCEPTION WHEN others THEN\n  RETURN false;\nEND\n$function$;","CREATE OR REPLACE FUNCTION public.demo_hub_signature_name_matches(p_typed text, p_employee text)\n RETURNS boolean\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''\nAS $function$\n SELECT length(btrim(COALESCE(p_typed,''))) >= 2\n    AND lower(regexp_replace(btrim(COALESCE(p_typed,'')),'[[:space:]]+',' ','g'))\n      = lower(regexp_replace(btrim(COALESCE(p_employee,'')),'[[:space:]]+',' ','g'));\n$function$;","CREATE OR REPLACE FUNCTION public.demo_sync_work_order_assignments_on_complete()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nBEGIN\n  IF NEW.status = 'completed' AND (OLD.status IS DISTINCT FROM 'completed') THEN\n    UPDATE public.demo_work_order_assignments\n    SET status = 'completed', updated_at = now()\n    WHERE work_request_id = NEW.id AND status = 'active';\n  END IF;\n  RETURN NEW;\nEND;\n$function$;","CREATE OR REPLACE FUNCTION public.demo_ops_manual_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nBEGIN\n  -- PostgreSQL fills generated columns after BEFORE triggers; the immutable id fixes the path.\n  IF TG_OP='DELETE' OR (to_jsonb(NEW)-ARRAY['upload_state','ready_at','storage_path']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['upload_state','ready_at','storage_path'])\n    OR OLD.upload_state<>'pending' OR NEW.upload_state<>'ready' OR NEW.ready_at IS NULL THEN\n    RAISE EXCEPTION 'Published manuals and upload identities are immutable' USING ERRCODE='42501';\n  END IF;\n  RETURN NEW;\nEND $function$;","CREATE OR REPLACE FUNCTION public.demo_hub_verify_safety(p_token uuid, p_data jsonb, p_auth_user uuid, p_session_id uuid, p_verified_at timestamp with time zone)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nDECLARE actor public.demo_employees%ROWTYPE; r public.demo_work_requests%ROWTYPE; evidence uuid; result jsonb;\nBEGIN\n SELECT * INTO actor FROM public.demo_hub_actor(p_token);\n IF actor.id IS NULL OR actor.role<>'manager' OR NOT actor.hub_approval_enabled THEN\n  RAISE EXCEPTION 'Authorized manager required' USING ERRCODE='42501'; END IF;\n IF NOT EXISTS(SELECT FROM public.demo_hub_manager_identities WHERE employee_id=actor.id AND auth_user_id=p_auth_user AND enabled)\n OR NOT EXISTS(SELECT FROM auth.sessions WHERE id=p_session_id AND user_id=p_auth_user AND (not_after IS NULL OR not_after>now()))\n OR p_verified_at IS NULL OR p_verified_at NOT BETWEEN now()-interval '5 minutes' AND now() THEN\n  RAISE EXCEPTION 'Independent manager identity verification required' USING ERRCODE='42501'; END IF;\n IF p_data->>'passed' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Pass decision required' USING ERRCODE='22023'; END IF;\n SELECT * INTO r FROM public.demo_work_requests WHERE id=(p_data->>'id')::uuid FOR UPDATE;\n IF NOT FOUND THEN RAISE EXCEPTION 'Order not found' USING ERRCODE='P0002'; END IF;\n IF EXISTS(SELECT FROM public.demo_hub_operations WHERE actor_id=actor.id AND operation_id=(p_data->>'operation_id')::uuid) THEN\n  RETURN public.demo_hub_workflow(p_token,'verify',p_data);\n END IF;\n IF NOT COALESCE((SELECT enabled FROM public.demo_hub_feature_flags WHERE feature='safety_release_workflow'),false)\n OR r.status<>'awaiting_verification' OR NOT (r.is_safety_critical OR r.safety_hold)\n OR r.version IS DISTINCT FROM (p_data->>'version')::integer THEN\n  RAISE EXCEPTION 'Safety release unavailable or order changed' USING ERRCODE='42501'; END IF;\n INSERT INTO public.demo_hub_manager_stepup_attestations(actor_id,work_request_id,completion_revision,method,verified_at)\n VALUES(actor.id,r.id,r.completion_revision,'independent_verified_channel',p_verified_at) RETURNING id INTO evidence;\n result:=public.demo_hub_workflow(p_token,'verify',p_data||jsonb_build_object('manager_stepup_id',evidence));\n UPDATE public.demo_hub_operations SET input=p_data WHERE actor_id=actor.id AND operation_id=(p_data->>'operation_id')::uuid;\n RETURN result;\nEND;\n$function$;","CREATE OR REPLACE FUNCTION public.demo_ops_validate_manual_replacement()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nDECLARE previous public.demo_ops_ride_manuals%rowtype; corrected public.demo_ops_ride_manuals%rowtype;\nBEGIN\n  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Manual revisions are immutable' USING ERRCODE='42501'; END IF;\n  SELECT * INTO previous FROM public.demo_ops_ride_manuals WHERE id=NEW.previous_id;\n  SELECT * INTO corrected FROM public.demo_ops_ride_manuals WHERE id=NEW.replacement_id;\n  IF previous.id IS NULL OR corrected.id IS NULL OR previous.id=corrected.id\n    OR previous.upload_state<>'ready' OR corrected.upload_state<>'ready'\n    OR previous.source_file<>corrected.source_file OR previous.title<>corrected.title\n    OR previous.kind<>corrected.kind OR previous.language<>corrected.language\n    OR previous.revision<>corrected.revision OR previous.file_name<>corrected.file_name\n    OR corrected.uploader_id<>NEW.corrected_by OR previous.sha256=corrected.sha256\n    OR EXISTS (SELECT 1 FROM public.demo_ops_manual_replacements WHERE previous_id=NEW.replacement_id)\n    OR NOT EXISTS (SELECT 1 FROM public.demo_employees WHERE id=NEW.corrected_by AND role='manager' AND active AND hub_access_enabled AND NOT hub_access_blocked) THEN\n    RAISE EXCEPTION 'Invalid corrected manual revision' USING ERRCODE='23514';\n  END IF;\n  RETURN NEW;\nEND $function$;","CREATE OR REPLACE FUNCTION public.demo_ops_manuals(p_token uuid, p_action text, p_data jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nDECLARE\n  actor public.demo_employees%rowtype;\n  saved public.demo_ops_ride_manuals%rowtype;\n  manual_id uuid;\n  next_manual_id uuid;\n  revision_depth integer;\n  result jsonb;\n  source_name text;\nBEGIN\n  actor:=public.demo_hub_actor(p_token);\n  IF actor.id IS NULL THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='28000'; END IF;\n  IF actor.role NOT IN ('employee','shop','manager') THEN RAISE EXCEPTION 'Staff access required' USING ERRCODE='42501'; END IF;\n  IF jsonb_typeof(p_data) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Invalid fields' USING ERRCODE='22023'; END IF;\n  IF p_action='access' THEN\n    IF p_data<>'{}'::jsonb THEN RAISE EXCEPTION 'Invalid fields' USING ERRCODE='22023'; END IF;\n    RETURN jsonb_build_object('can_upload',actor.role='manager');\n  ELSIF p_action='list' THEN\n    IF (p_data-'source')<>'{}'::jsonb OR jsonb_typeof(p_data->'source') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'Invalid ride' USING ERRCODE='22023'; END IF;\n    source_name:=p_data->>'source';\n    IF source_name='' THEN\n      SELECT coalesce(jsonb_agg(q.record),'[]'::jsonb) INTO result FROM (\n        SELECT jsonb_build_object('source_file',s.source_file,'ride_name',s.ride_name,'manual_count',count(m.id)) AS record\n        FROM public.demo_ops_manual_sources s LEFT JOIN public.demo_ops_ride_manuals m ON m.source_file=ANY(public.demo_ops_manual_folder_sources(s.source_file)) AND m.upload_state='ready'\n          AND NOT EXISTS (SELECT 1 FROM public.demo_ops_manual_replacements r WHERE r.previous_id=m.id)\n        GROUP BY s.source_file,s.ride_name ORDER BY s.ride_name\n      ) q;\n      RETURN jsonb_build_object('sources',result,'can_upload',actor.role='manager');\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM public.demo_ops_manual_sources WHERE source_file=source_name) THEN RAISE EXCEPTION 'Manual folder not found / Carpeta de manuales no encontrada' USING ERRCODE='P0002'; END IF;\n    SELECT coalesce(jsonb_agg(q.record),'[]'::jsonb) INTO result FROM (\n      SELECT to_jsonb(m)-ARRAY['storage_path','sha256','uploader_id','upload_state','is_test'] AS record\n      FROM public.demo_ops_ride_manuals m WHERE m.source_file=ANY(public.demo_ops_manual_folder_sources(source_name)) AND m.upload_state='ready'\n        AND NOT EXISTS (SELECT 1 FROM public.demo_ops_manual_replacements r WHERE r.previous_id=m.id)\n        ORDER BY ready_at DESC,id\n    ) q;\n    RETURN jsonb_build_object('documents',result,'source_name',(SELECT s.ride_name FROM public.demo_ops_manual_sources s WHERE s.source_file=source_name),'can_upload',actor.role='manager');\n  END IF;\n  IF p_action NOT IN ('reserve','upload','commit','view') THEN RAISE EXCEPTION 'Invalid action' USING ERRCODE='22023'; END IF;\n  IF coalesce(p_data->>'id','') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$' THEN RAISE EXCEPTION 'Invalid manual identity' USING ERRCODE='22023'; END IF;\n  manual_id:=(p_data->>'id')::uuid;\n  IF p_action<>'view' AND actor.role<>'manager' THEN RAISE EXCEPTION 'Only managers can upload manuals / Solo gerentes pueden subir manuales' USING ERRCODE='42501'; END IF;\n  IF p_action='reserve' THEN\n    IF (p_data-ARRAY['id','source','title','kind','language','revision','file_name','sha256','byte_size'])<>'{}'::jsonb\n      OR NOT p_data ?& ARRAY['id','source','title','kind','language','revision','file_name','sha256','byte_size']\n      OR EXISTS (SELECT 1 FROM jsonb_each(p_data-'byte_size') f WHERE jsonb_typeof(f.value)<>'string')\n      OR jsonb_typeof(p_data->'byte_size') IS DISTINCT FROM 'number'\n      OR coalesce(p_data->>'byte_size','') !~ '^[0-9]{1,8}$'\n      OR (p_data->>'byte_size')::integer NOT BETWEEN 20 AND 20971520\n      OR length(trim(p_data->>'title')) NOT BETWEEN 2 AND 160 OR p_data->>'title' ~ '[[:cntrl:]]'\n      OR p_data->>'kind' NOT IN ('operator','maintenance','emergency','other')\n      OR p_data->>'language' NOT IN ('en','es','both','other')\n      OR length(p_data->>'revision')>80 OR p_data->>'revision' ~ '[[:cntrl:]]'\n      OR length(p_data->>'file_name') NOT BETWEEN 5 AND 200 OR p_data->>'file_name' ~ '[[:cntrl:]]'\n      OR lower(right(p_data->>'file_name',4))<>'.pdf'\n      OR p_data->>'sha256' !~ '^[0-9a-f]{64}$'\n      OR NOT EXISTS (SELECT 1 FROM public.demo_ops_manual_sources WHERE source_file=p_data->>'source') THEN\n      RAISE EXCEPTION 'Choose a folder, title, and PDF up to 20 MiB / Elija carpeta, título y PDF de hasta 20 MiB' USING ERRCODE='22023';\n    END IF;\n    PERFORM pg_advisory_xact_lock(hashtextextended(manual_id::text,0));\n    SELECT * INTO saved FROM public.demo_ops_ride_manuals WHERE id=manual_id;\n    IF FOUND THEN\n      IF saved.uploader_id<>actor.id THEN RAISE EXCEPTION 'Manual not found' USING ERRCODE='P0002'; END IF;\n      IF saved.source_file<>p_data->>'source' OR saved.title<>p_data->>'title' OR saved.kind<>p_data->>'kind'\n        OR saved.language<>p_data->>'language' OR saved.revision<>p_data->>'revision' OR saved.file_name<>p_data->>'file_name'\n        OR saved.sha256<>p_data->>'sha256' OR saved.byte_size<>(p_data->>'byte_size')::integer THEN\n        RAISE EXCEPTION 'Upload changed. Start a new upload / Inicie otra carga' USING ERRCODE='PT409';\n      END IF;\n    ELSE\n      INSERT INTO public.demo_ops_ride_manuals(id,source_file,title,kind,language,revision,file_name,sha256,byte_size,uploader_id,uploader_name)\n      VALUES (manual_id,p_data->>'source',p_data->>'title',p_data->>'kind',p_data->>'language',p_data->>'revision',p_data->>'file_name',p_data->>'sha256',(p_data->>'byte_size')::integer,actor.id,actor.full_name)\n      RETURNING * INTO saved;\n    END IF;\n    RETURN jsonb_build_object('id',saved.id,'upload_state',saved.upload_state);\n  END IF;\n  IF (p_data-'id')<>'{}'::jsonb THEN RAISE EXCEPTION 'Invalid fields' USING ERRCODE='22023'; END IF;\n  IF p_action='view' THEN\n    FOR revision_depth IN 1..64 LOOP\n      SELECT replacement_id INTO next_manual_id FROM public.demo_ops_manual_replacements WHERE previous_id=manual_id;\n      EXIT WHEN NOT FOUND;\n      manual_id:=next_manual_id;\n    END LOOP;\n    IF EXISTS (SELECT 1 FROM public.demo_ops_manual_replacements WHERE previous_id=manual_id) THEN\n      RAISE EXCEPTION 'Manual revision unavailable' USING ERRCODE='P0002';\n    END IF;\n  END IF;\n  SELECT * INTO saved FROM public.demo_ops_ride_manuals WHERE id=manual_id FOR UPDATE;\n  IF NOT FOUND OR (p_action<>'view' AND saved.uploader_id<>actor.id) OR (p_action='view' AND saved.upload_state<>'ready') THEN\n    RAISE EXCEPTION 'Manual not found' USING ERRCODE='P0002';\n  END IF;\n  IF p_action='commit' AND saved.upload_state='pending' THEN\n    IF NOT EXISTS (SELECT 1 FROM storage.objects o WHERE o.bucket_id='hub-ride-manuals' AND o.name='demo/'||saved.storage_path\n      AND (o.metadata->>'size')::bigint=saved.byte_size AND o.metadata->>'mimetype'='application/pdf') AND NOT EXISTS (SELECT 1 FROM public.hub_r2_manual_receipts r WHERE r.object_key='manuals/'||saved.storage_path AND r.byte_size=saved.byte_size AND r.sha256=saved.sha256) THEN\n      RAISE EXCEPTION 'PDF upload is incomplete. Retry / Reintente la carga' USING ERRCODE='PT409';\n    END IF;\n    UPDATE public.demo_ops_ride_manuals SET upload_state='ready',ready_at=clock_timestamp() WHERE id=manual_id RETURNING * INTO saved;\n  END IF;\n  RETURN jsonb_build_object('id',saved.id,'storage_path',saved.storage_path,'file_name',saved.file_name,'byte_size',saved.byte_size,'sha256',saved.sha256,'upload_state',saved.upload_state);\nEND $function$;","CREATE OR REPLACE FUNCTION public.demo_hub_part_photo(p_token uuid, p_action text, p_part_id uuid DEFAULT NULL::uuid, p_photo_id uuid DEFAULT NULL::uuid, p_sha256 text DEFAULT NULL::text, p_bytes integer DEFAULT NULL::integer)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nDECLARE actor public.demo_employees%ROWTYPE; part public.demo_hub_parts%ROWTYPE;\n  photo public.demo_hub_part_photos%ROWTYPE; can_write boolean;\nBEGIN\n  SELECT * INTO actor FROM public.demo_hub_actor(p_token);\n  IF NOT FOUND OR actor.id IS NULL THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='28000'; END IF;\n  IF p_action IS NULL OR p_action NOT IN ('list','reserve','commit','view') THEN RAISE EXCEPTION 'Invalid action' USING ERRCODE='22023'; END IF;\n  IF p_action IN ('view','commit') THEN\n    SELECT * INTO photo FROM public.demo_hub_part_photos WHERE id=p_photo_id;\n    IF NOT FOUND THEN RAISE EXCEPTION 'Not found' USING ERRCODE='P0002'; END IF;\n    p_part_id := photo.part_id;\n  END IF;\n  SELECT * INTO part FROM public.demo_hub_parts WHERE id=p_part_id FOR UPDATE;\n  IF NOT FOUND OR (actor.role='manager' OR (p_action IN ('list','view') AND part.pickup_employee_id=actor.id) OR (actor.role='shop' AND part.requested_by=actor.id)\n    OR EXISTS(SELECT FROM public.demo_work_requests w WHERE w.id=part.work_request_id AND NOT w.hub_draft\n      AND (w.assigned_to=actor.id OR EXISTS(SELECT FROM public.demo_work_order_assignments a\n        WHERE a.work_request_id=w.id AND a.employee_id=actor.id AND a.status='active')))) IS NOT TRUE THEN\n    RAISE EXCEPTION 'Not found' USING ERRCODE='P0002';\n  END IF;\n  IF part.work_request_id IS NOT NULL AND EXISTS(SELECT FROM public.demo_work_requests WHERE id=part.work_request_id AND hub_draft) THEN\n    RAISE EXCEPTION 'Not found' USING ERRCODE='P0002';\n  END IF;\n  can_write := actor.role IN ('employee','manager','shop') AND (actor.role='manager' OR part.requested_by=actor.id)\n    AND part.state NOT IN ('denied','installed');\n  IF p_action='list' THEN\n    RETURN jsonb_build_object('can_upload',can_write,'photos',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',id,'created_at',created_at))\n      FROM public.demo_hub_part_photos WHERE part_id=part.id AND upload_state='ready'),'[]'::jsonb));\n  END IF;\n  IF p_action='view' THEN\n    IF photo.upload_state<>'ready' THEN RAISE EXCEPTION 'Not found' USING ERRCODE='P0002'; END IF;\n    RETURN jsonb_build_object('path',photo.storage_path,'sha256',photo.sha256,'bytes',photo.byte_size);\n  END IF;\n  IF NOT can_write THEN RAISE EXCEPTION 'Upload not allowed' USING ERRCODE='42501'; END IF;\n  IF p_action='reserve' THEN\n    IF p_photo_id IS NULL OR p_sha256 IS NULL OR p_sha256 !~ '^[0-9a-f]{64}$' OR p_bytes IS NULL OR p_bytes NOT BETWEEN 1 AND 5242880 THEN\n      RAISE EXCEPTION 'Invalid photo' USING ERRCODE='22023';\n    END IF;\n    SELECT * INTO photo FROM public.demo_hub_part_photos WHERE part_id=part.id;\n    IF FOUND THEN\n      IF photo.id<>p_photo_id OR photo.uploaded_by<>actor.id OR photo.sha256<>p_sha256 OR photo.byte_size<>p_bytes THEN\n        RAISE EXCEPTION 'Photo already exists or retry changed' USING ERRCODE='23505';\n      END IF;\n    ELSE\n      INSERT INTO public.demo_hub_part_photos(part_id,id,storage_path,uploaded_by,byte_size,sha256)\n      VALUES(part.id,p_photo_id,'parts/'||part.id||'/'||p_photo_id||'.jpg',actor.id,p_bytes,p_sha256) RETURNING * INTO photo;\n    END IF;\n    RETURN jsonb_build_object('id',photo.id,'path',photo.storage_path,'state',photo.upload_state);\n  END IF;\n  IF photo.uploaded_by<>actor.id THEN RAISE EXCEPTION 'Not found' USING ERRCODE='P0002'; END IF;\n  IF NOT EXISTS(SELECT FROM storage.objects WHERE bucket_id='hub-work-order-photos' AND name='demo/'||photo.storage_path\n    AND (metadata->>'size')::bigint=photo.byte_size) AND NOT EXISTS(SELECT FROM public.hub_r2_receipts WHERE object_key=photo.storage_path AND byte_size=photo.byte_size AND sha256=photo.sha256) THEN RAISE EXCEPTION 'Upload incomplete' USING ERRCODE='22023'; END IF;\n  UPDATE public.demo_hub_part_photos SET upload_state='ready' WHERE id=photo.id;\n  RETURN jsonb_build_object('id',photo.id,'state','ready');\nEND;\n$function$;","REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA demo_hub_auth FROM PUBLIC,anon,authenticated;","REVOKE ALL ON FUNCTION public.demo_ops_manual_folder_sources(p_source text) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_ops_manual_folder_sources(p_source text) TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_photo_replace(p_token uuid, p_action text, p_original_id uuid, p_photo_id uuid, p_sha256 text, p_bytes integer, p_reason text) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_photo_replace(p_token uuid, p_action text, p_original_id uuid, p_photo_id uuid, p_sha256 text, p_bytes integer, p_reason text) TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_backup_photo_permission(p_secret text, p_photo_id uuid) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_backup_photo_permission(p_secret text, p_photo_id uuid) TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_auth_delivery(p_id uuid, p_state text, p_receipt text) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_auth_delivery(p_id uuid, p_state text, p_receipt text) TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_completion(p_token uuid, p_action text, p_request_id uuid, p_photo_id uuid, p_sha256 text, p_bytes integer, p_notes text, p_signature text, p_signer_name text) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_completion(p_token uuid, p_action text, p_request_id uuid, p_photo_id uuid, p_sha256 text, p_bytes integer, p_notes text, p_signature text, p_signer_name text) TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_photo(p_token uuid, p_action text, p_request_id uuid, p_photo_id uuid, p_sha256 text, p_bytes integer) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_photo(p_token uuid, p_action text, p_request_id uuid, p_photo_id uuid, p_sha256 text, p_bytes integer) TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_translation_access(p_token uuid) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_translation_access(p_token uuid) TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_translation_cache_get(p_hashes text[]) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_translation_cache_get(p_hashes text[]) TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_translation_cache_put(p_rows jsonb) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_translation_cache_put(p_rows jsonb) TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_inspections(p_token uuid, p_action text, p_data jsonb) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_inspections(p_token uuid, p_action text, p_data jsonb) TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_workflow(p_token uuid, p_action text, p_data jsonb) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_workflow(p_token uuid, p_action text, p_data jsonb) TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_report(p_token uuid, p_asset uuid, p_start date, p_end date, p_status text, p_offset integer) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_report(p_token uuid, p_asset uuid, p_start date, p_end date, p_status text, p_offset integer) TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_snapshot(p_token uuid) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_snapshot(p_token uuid) TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_assistant_allow(p_token uuid) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_assistant_allow(p_token uuid) TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_snapshot_page(p_token uuid, p_cursor jsonb) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_snapshot_page(p_token uuid, p_cursor jsonb) TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_actor(p_token uuid) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_actor(p_token uuid) TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_authentication(p_token uuid, p_action text, p_data jsonb) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_authentication(p_token uuid, p_action text, p_data jsonb) TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_health(p_token uuid) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_health(p_token uuid) TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_validate_troubleshooting_guide(p_guide jsonb) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_validate_troubleshooting_guide(p_guide jsonb) TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_troubleshooting_workflow(p_token uuid, p_action text, p_data jsonb) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_troubleshooting_workflow(p_token uuid, p_action text, p_data jsonb) TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_record_activity(p_token uuid) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_record_activity(p_token uuid) TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_valid_png_signature(p_signature text) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_valid_png_signature(p_signature text) TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_signature_name_matches(p_typed text, p_employee text) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_signature_name_matches(p_typed text, p_employee text) TO service_role;","REVOKE ALL ON FUNCTION public.demo_sync_work_order_assignments_on_complete() FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_sync_work_order_assignments_on_complete() TO service_role;","REVOKE ALL ON FUNCTION public.demo_ops_manual_immutable() FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_ops_manual_immutable() TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_verify_safety(p_token uuid, p_data jsonb, p_auth_user uuid, p_session_id uuid, p_verified_at timestamp with time zone) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_verify_safety(p_token uuid, p_data jsonb, p_auth_user uuid, p_session_id uuid, p_verified_at timestamp with time zone) TO service_role;","REVOKE ALL ON FUNCTION public.demo_ops_validate_manual_replacement() FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_ops_validate_manual_replacement() TO service_role;","REVOKE ALL ON FUNCTION public.demo_ops_manuals(p_token uuid, p_action text, p_data jsonb) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_ops_manuals(p_token uuid, p_action text, p_data jsonb) TO service_role;","REVOKE ALL ON FUNCTION public.demo_hub_part_photo(p_token uuid, p_action text, p_part_id uuid, p_photo_id uuid, p_sha256 text, p_bytes integer) FROM PUBLIC,anon,authenticated;","GRANT EXECUTE ON FUNCTION public.demo_hub_part_photo(p_token uuid, p_action text, p_part_id uuid, p_photo_id uuid, p_sha256 text, p_bytes integer) TO service_role;","CREATE TRIGGER demo_sync_assignments AFTER UPDATE OF status ON public.demo_work_requests FOR EACH ROW EXECUTE FUNCTION public.demo_sync_work_order_assignments_on_complete();","CREATE TRIGGER demo_manuals_immutable BEFORE DELETE OR UPDATE ON public.demo_ops_ride_manuals FOR EACH ROW EXECUTE FUNCTION public.demo_ops_manual_immutable();","CREATE TRIGGER demo_manual_replacements BEFORE INSERT OR DELETE OR UPDATE ON public.demo_ops_manual_replacements FOR EACH ROW EXECUTE FUNCTION public.demo_ops_validate_manual_replacement();"]$template_json$::jsonb) LOOP
  EXECUTE replace(replace(command,'demo_',p_company||'_'),'demo/',p_company||'/');
 END LOOP;
 PERFORM vault.create_secret(encode(extensions.gen_random_bytes(32),'hex'),p_company||'_pms_hub_signin_key','Independent Teamstead server-only secret');
 PERFORM vault.create_secret(encode(extensions.gen_random_bytes(32),'hex'),p_company||'_pms_hub_backup_export_secret','Independent Teamstead server-only secret');
END $functionx$
;
